CREATE OR REPLACE FUNCTION "lms"."block_ledger_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION 'CLOCK_HOUR_LEDGER_IS_IMMUTABLE: Use superseding entry via void_and_reissue, not direct UPDATE/DELETE. Attempted % on row %', TG_OP, OLD.id;
END;
$$;


ALTER FUNCTION "lms"."block_ledger_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."build_open_badge_json"("p_learner_badge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
    SELECT jsonb_build_object(
        '@context', 'https://w3id.org/openbadges/v3',
        'type', 'Assertion',
        'id', lb.verification_code,
        'recipient', jsonb_build_object(
            'type', 'uuid',
            'identity', lb.learner_user_id
        ),
        'badge', jsonb_build_object(
            'type', 'BadgeClass',
            'id', b.id,
            'name', b.name,
            'description', COALESCE(b.description, ''),
            'image', COALESCE(b.icon_url, ''),
            'criteria', b.criteria
        ),
        'issuedOn', extract(epoch from lb.awarded_at),
        'verification', jsonb_build_object(
            'type', 'HostedBadge'
        )
    )
    FROM lms.learner_badges lb
    JOIN lms.badges b ON lb.badge_id = b.id
    WHERE lb.id = p_learner_badge_id;
$$;


ALTER FUNCTION "lms"."build_open_badge_json"("p_learner_badge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."can_access_minor_data"("p_tenant_id" "uuid", "p_minor_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $_$
DECLARE v_exists boolean;
BEGIN
    IF lms.is_platform_admin() THEN RETURN true; END IF;
    IF lms.is_lms_admin(p_tenant_id) THEN RETURN true; END IF;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM lms.guardian_consents WHERE minor_user_id = $1 AND guardian_user_id = $2 AND consent_status = $3 AND (expires_at IS NULL OR expires_at > now()))')
        INTO v_exists USING p_minor_user_id, auth.uid(), 'granted';
    RETURN v_exists;
END;
$_$;


ALTER FUNCTION "lms"."can_access_minor_data"("p_tenant_id" "uuid", "p_minor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."can_view_learner"("p_tenant_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $_$
DECLARE v_exists boolean;
BEGIN
    IF lms.is_platform_admin() THEN RETURN true; END IF;
    IF lms.is_instructor(p_tenant_id) THEN RETURN true; END IF;
    IF p_user_id = auth.uid() AND lms.is_tenant_member(p_tenant_id) THEN RETURN true; END IF;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM lms.lms_roles WHERE tenant_id = $1 AND user_id = $2 AND status = $3 AND role = $4)')
        INTO v_exists USING p_tenant_id, auth.uid(), 'active', 'support_navigator';
    IF v_exists THEN RETURN true; END IF;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM lms.navigator_caseloads WHERE tenant_id = $1 AND navigator_user_id = $2 AND learner_user_id = $3 AND status = $4)')
        INTO v_exists USING p_tenant_id, auth.uid(), p_user_id, 'active';
    RETURN v_exists;
END;
$_$;


ALTER FUNCTION "lms"."can_view_learner"("p_tenant_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."check_course_completion"("p_tenant_id" "uuid", "p_enrollment_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_course_id uuid;
    v_completion_rule_type text;
    v_completion_rule_config jsonb;
    v_total_lessons integer;
    v_completed_lessons integer;
    v_passing_score numeric(5,2);
    v_avg_quiz_score numeric(5,2);
    v_required_hours numeric(8,2);
    v_actual_hours numeric(8,2);
BEGIN
    SELECT e.course_id INTO v_course_id
    FROM lms.enrollments e
    WHERE e.tenant_id = p_tenant_id AND e.id = p_enrollment_id;

    IF v_course_id IS NULL THEN
        RETURN false;
    END IF;

    SELECT cr.rule_type, cr.rule_config, cr.min_percentage, cr.required_clock_hours
    INTO v_completion_rule_type, v_completion_rule_config, v_passing_score, v_required_hours
    FROM lms.completion_rules cr
    WHERE cr.tenant_id = p_tenant_id AND cr.course_id = v_course_id AND cr.is_active = true
    LIMIT 1;

    IF v_completion_rule_type IS NULL THEN
        v_completion_rule_type := 'all_lessons';
    END IF;

    -- Count lessons
    SELECT COUNT(*), COUNT(*) FILTER (WHERE lp.status = 'completed')
    INTO v_total_lessons, v_completed_lessons
    FROM lms.lessons l
    LEFT JOIN lms.lesson_progress lp ON lp.tenant_id = l.tenant_id AND lp.lesson_id = l.id AND lp.enrollment_id = p_enrollment_id
    WHERE l.tenant_id = p_tenant_id AND l.course_id = v_course_id;

    -- Get actual clock hours
    v_actual_hours := lms.get_learner_computed_hours(p_tenant_id, (SELECT learner_user_id FROM lms.enrollments WHERE id = p_enrollment_id));

    CASE v_completion_rule_type
        WHEN 'all_lessons' THEN
            RETURN v_completed_lessons = v_total_lessons AND v_total_lessons > 0;
        WHEN 'min_lessons_percentage' THEN
            RETURN v_total_lessons > 0 AND (v_completed_lessons::numeric / v_total_lessons * 100) >= COALESCE(v_passing_score, 70);
        WHEN 'clock_hours_complete' THEN
            RETURN v_required_hours IS NOT NULL AND v_actual_hours >= v_required_hours;
        WHEN 'mixed' THEN
            RETURN v_completed_lessons = v_total_lessons AND v_total_lessons > 0
               AND (v_required_hours IS NULL OR v_actual_hours >= v_required_hours);
        ELSE
            RETURN v_completed_lessons = v_total_lessons AND v_total_lessons > 0;
    END CASE;
END;
$$;


ALTER FUNCTION "lms"."check_course_completion"("p_tenant_id" "uuid", "p_enrollment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."clock_hour_ledger_void_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
BEGIN
    -- Only allow changes to void-related fields and verification fields
    IF NEW.voided_at IS NOT NULL AND OLD.voided_at IS NULL THEN
        -- This is a void operation - allowed
        IF NEW.voided_by IS NULL THEN
            RAISE EXCEPTION 'CLOCK_HOUR_LEDGER_VOID_REQUIRES_VOIDED_BY';
        END IF;
        IF NEW.void_reason IS NULL OR BTRIM(NEW.void_reason) = '' THEN
            RAISE EXCEPTION 'CLOCK_HOUR_LEDGER_VOID_REQUIRES_REASON';
        END IF;
        IF NEW.verification_status <> 'voided' THEN
            RAISE EXCEPTION 'CLOCK_HOUR_LEDGER_VOID_MUST_SET_VERIFICATION_STATUS_VOIDED';
        END IF;
        RETURN NEW;
    END IF;
    
    -- Allow verification status updates (human verification)
    IF OLD.verification_status = 'computed' AND NEW.verification_status IN ('human_verified', 'ai_verified_pending_human') THEN
        IF NEW.verification_status = 'human_verified' AND NEW.verified_by IS NULL THEN
            RAISE EXCEPTION 'CLOCK_HOUR_LEDGER_VERIFICATION_REQUIRES_VERIFIED_BY';
        END IF;
        RETURN NEW;
    END IF;
    
    -- Block all other updates
    RAISE EXCEPTION 'CLOCK_HOUR_LEDGER_IS_IMMUTABLE: Only voiding and verification status updates are permitted. Attempted UPDATE on row %', OLD.id;
END;
$$;


ALTER FUNCTION "lms"."clock_hour_ledger_void_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."competency_rank"("p_level" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
    SELECT CASE p_level
        WHEN 'mastered'    THEN 3
        WHEN 'practiced'   THEN 2
        WHEN 'introduced'  THEN 1
        WHEN 'not_started' THEN 0
        ELSE 0
    END;
$$;


ALTER FUNCTION "lms"."competency_rank"("p_level" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "lms"."competency_rank"("p_level" "text") IS 'Single ordering for competency levels. Every comparison of mastery must go through this so introduced < practiced < mastered is defined in exactly one place.';



CREATE OR REPLACE FUNCTION "lms"."compute_all_leaderboard_snapshots"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_count integer := 0;
    lb RECORD;
BEGIN
    FOR lb IN SELECT id, tenant_id FROM lms.leaderboards WHERE p_tenant_id IS NULL OR tenant_id = p_tenant_id LOOP
        PERFORM lms.compute_leaderboard_snapshot(lb.tenant_id, lb.id);
        v_count := v_count + 1;
    END LOOP;
    RETURN v_count;
END;
$$;


ALTER FUNCTION "lms"."compute_all_leaderboard_snapshots"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."compute_leaderboard_snapshot"("p_tenant_id" "uuid", "p_leaderboard_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_snapshot_id uuid;
    v_leaderboard_type text;
    v_course_id uuid;
    v_cohort_id uuid;
    v_rankings jsonb;
    v_count integer;
BEGIN
    SELECT leaderboard_type, course_id, cohort_id, rankings
    INTO v_leaderboard_type, v_course_id, v_cohort_id, v_rankings
    FROM lms.leaderboards
    WHERE id = p_leaderboard_id AND tenant_id = p_tenant_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Leaderboard % not found in tenant %', p_leaderboard_id, p_tenant_id;
    END IF;

    v_count := COALESCE(jsonb_array_length(v_rankings), 0);

    INSERT INTO lms.leaderboard_snapshots (tenant_id, leaderboard_id, snapshot_date, snapshot_period, rankings, total_participants, computed_at)
    VALUES (p_tenant_id, p_leaderboard_id, CURRENT_DATE, v_leaderboard_type, v_rankings, v_count, now())
    ON CONFLICT (tenant_id, leaderboard_id, snapshot_date, snapshot_period)
    DO UPDATE SET rankings = EXCLUDED.rankings, total_participants = EXCLUDED.total_participants, computed_at = now(), updated_at = now()
    RETURNING id INTO v_snapshot_id;

    RETURN v_snapshot_id;
END;
$$;


ALTER FUNCTION "lms"."compute_leaderboard_snapshot"("p_tenant_id" "uuid", "p_leaderboard_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."create_superseding_entry"("p_tenant_id" "uuid", "p_original_ledger_id" "uuid", "p_corrected_minutes" numeric, "p_corrected_by" "uuid", "p_correction_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_original RECORD;
    v_new_id uuid;
BEGIN
    SELECT * INTO v_original FROM lms.clock_hour_ledger
    WHERE tenant_id = p_tenant_id AND id = p_original_ledger_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORIGINAL_ENTRY_NOT_FOUND';
    END IF;

    IF v_original.voided_at IS NOT NULL THEN
        RAISE EXCEPTION 'ORIGINAL_ENTRY_ALREADY_VOIDED';
    END IF;

    -- Void the original
    PERFORM lms.void_clock_hour_entry(p_tenant_id, p_original_ledger_id, p_corrected_by, p_correction_reason);

    -- Create superseding entry
    INSERT INTO lms.clock_hour_ledger (
        tenant_id, learner_user_id, enrollment_id, course_id,
        lesson_id, module_id, source_type, source_id,
        computed_minutes, verified_minutes,
        verification_status, verified_by, verified_at,
        verification_notes, supersedes_ledger_id,
        session_started_at, session_ended_at, metadata
    ) VALUES (
        v_original.tenant_id, v_original.learner_user_id, v_original.enrollment_id, v_original.course_id,
        v_original.lesson_id, v_original.module_id, 'system_adjustment', v_original.source_id,
        p_corrected_minutes, p_corrected_minutes,
        'human_verified', p_corrected_by, now(),
        p_correction_reason, p_original_ledger_id,
        v_original.session_started_at, v_original.session_ended_at,
        jsonb_build_object('correction', true, 'original_minutes', v_original.computed_minutes, 'reason', p_correction_reason)
    )
    RETURNING id INTO v_new_id;

    RETURN v_new_id;
END;
$$;


ALTER FUNCTION "lms"."create_superseding_entry"("p_tenant_id" "uuid", "p_original_ledger_id" "uuid", "p_corrected_minutes" numeric, "p_corrected_by" "uuid", "p_correction_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."credential_requirements_met"("p_tenant_id" "uuid", "p_credential_definition_id" "uuid", "p_learner_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
    SELECT bool_and(
        CASE req.requirement_type
            WHEN 'skill' THEN EXISTS (
                SELECT 1 FROM lms.skill_progress sp
                WHERE sp.tenant_id = p_tenant_id
                  AND sp.learner_user_id = p_learner_user_id
                  AND sp.skill_id = req.skill_id
                  AND sp.competency_level >= COALESCE(req.minimum_competency_level, 'practiced')
                  AND sp.is_signed_off = true
            )
            WHEN 'clock_hours' THEN EXISTS (
                SELECT 1 FROM lms.clock_hour_ledger chl
                WHERE chl.tenant_id = p_tenant_id
                  AND chl.learner_user_id = p_learner_user_id
                HAVING SUM(COALESCE(chl.verified_minutes, chl.computed_minutes, 0) / 60.0) >= req.required_clock_hours
            )
            WHEN 'course_completion' THEN EXISTS (
                SELECT 1 FROM lms.course_completions cc
                WHERE cc.tenant_id = p_tenant_id
                  AND cc.learner_user_id = p_learner_user_id
                  AND cc.course_id = req.course_id
                  AND (cc.is_passed = true OR cc.completed_at IS NOT NULL)
            )
            WHEN 'module_completion' THEN EXISTS (
                SELECT 1 FROM lms.module_progress mp
                WHERE mp.tenant_id = p_tenant_id
                  AND mp.learner_user_id = p_learner_user_id
                  AND mp.module_id = req.module_id
                  AND (mp.progress_percentage = 100 OR mp.status = 'completed')
            )
        END
    )
    FROM lms.credential_requirements req
    WHERE req.tenant_id = p_tenant_id
      AND req.credential_definition_id = p_credential_definition_id
      AND req.is_required = true;
$$;


ALTER FUNCTION "lms"."credential_requirements_met"("p_tenant_id" "uuid", "p_credential_definition_id" "uuid", "p_learner_user_id" "uuid") OWNER TO "postgres";


