CREATE OR REPLACE FUNCTION "lms"."fn_ai_escalation_route"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_reason  text;
  v_type    lms.human_escalation_routing.escalation_type%TYPE;
  v_prio    lms.human_escalation_routing.priority%TYPE;
  v_role    lms.human_escalation_routing.assigned_role%TYPE;
  v_route   uuid;
BEGIN
  IF NEW.escalation_triggered IS NOT TRUE THEN
    RETURN NULL;  -- no escalation signal on this row: nothing to route
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.escalation_triggered THEN
    RETURN NULL;  -- already escalated: routing exists from the first signal
  END IF;

  IF EXISTS (SELECT 1 FROM lms.human_escalation_routing r
             WHERE r.tenant_id = NEW.tenant_id AND r.session_id = NEW.id) THEN
    RETURN NULL;  -- idempotent per session
  END IF;

  v_reason := lower(coalesce(NEW.escalation_reason, ''));
  IF v_reason ~ '(crisis|suicid|self.harm)' THEN
    v_type := 'crisis';    v_prio := 'critical'; v_role := 'crisis_counselor';
  ELSIF v_reason ~ '(safety|harm|abuse)' THEN
    v_type := 'safety';    v_prio := 'urgent';    v_role := 'support_navigator';
  ELSIF v_reason ~ 'confus' THEN
    v_type := 'confusion'; v_prio := 'high';      v_role := 'instructor';
  ELSIF v_reason ~ '(frustrat|angry)' THEN
    v_type := 'frustration'; v_prio := 'high';    v_role := 'instructor';
  ELSIF v_reason ~ '(technical|error|bug)' THEN
    v_type := 'technical'; v_prio := 'high';      v_role := 'instructor';
  ELSIF v_reason ~ 'human' THEN
    v_type := 'human_request'; v_prio := 'high';  v_role := 'instructor';
  ELSE
    v_type := 'ai_limitation'; v_prio := 'high';  v_role := 'instructor';
  END IF;

  INSERT INTO lms.human_escalation_routing (
    tenant_id, session_id, learner_user_id, escalation_type, priority,
    assigned_role, status, escalation_context)
  VALUES (
    NEW.tenant_id, NEW.id, NEW.learner_user_id, v_type, v_prio,
    v_role, 'pending',
    jsonb_build_object('source', 'ai_teaching_session_trigger',
                       'escalation_reason', NEW.escalation_reason,
                       'delivery_mode', NEW.delivery_mode,
                       'session_status', NEW.session_status))
  RETURNING id INTO v_route;

  INSERT INTO lms.ai_escalation_queue (
    tenant_id, escalation_id, queue_position, is_auto_routed,
    routed_to_role, routed_at)
  VALUES (
    NEW.tenant_id, v_route,
    (SELECT COALESCE(MAX(queue_position), 0) + 1
       FROM lms.ai_escalation_queue WHERE tenant_id = NEW.tenant_id),
    true, v_role, now());

  IF v_type IN ('crisis', 'safety') THEN
    INSERT INTO lms.support_referrals (
      tenant_id, learner_user_id, referral_category, referral_source,
      description, status, priority, is_private_to_learner, metadata)
    VALUES (
      NEW.tenant_id, NEW.learner_user_id, 'other', 'ai_escalation',
      left(coalesce(NEW.escalation_reason,
        'AI teaching session raised a ' || v_type || ' escalation'), 500),
      'open',
      CASE WHEN v_prio = 'critical' THEN 'urgent' ELSE v_prio END,  -- referral CHECK domain has no 'critical'
      true,
      jsonb_build_object('session_id', NEW.id, 'routing_id', v_route,
                         'source', 'ai_escalation_trigger'));
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "lms"."fn_ai_escalation_route"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."fn_ai_session_minor_consent_gate"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM lms.minor_profiles mp
    WHERE mp.tenant_id = NEW.tenant_id
      AND mp.learner_user_id = NEW.learner_user_id
      AND mp.status = 'active')         -- 'emancipated'/'archived' pass
    AND NOT EXISTS (
      SELECT 1 FROM lms.guardian_consents g
      WHERE g.tenant_id = NEW.tenant_id
        AND g.minor_user_id = NEW.learner_user_id
        AND g.consent_status = 'granted'
        AND g.consent_type IN ('ai_teaching', 'all')
        AND (g.expires_at IS NULL OR g.expires_at > now()))
    AND NOT EXISTS (
      SELECT 1 FROM lms.minor_consent_guardrails m
      WHERE m.tenant_id = NEW.tenant_id
        AND m.learner_user_id = NEW.learner_user_id
        AND m.consent_status IN ('signed', 'renewed')
        AND (m.expires_at IS NULL OR m.expires_at > now()))
  THEN
    RAISE EXCEPTION 'MINOR_CONSENT_REQUIRED: no valid guardian consent (ai_teaching/all) for learner % in tenant % — AI teaching session blocked by minor-consent guardrail (tree domains 1/5/11)',
      NEW.learner_user_id, NEW.tenant_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "lms"."fn_ai_session_minor_consent_gate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."fn_announcement_fanout_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_module_id uuid;
BEGIN
  IF NOT NEW.is_published THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.is_published THEN RETURN NULL; END IF;

  IF NEW.audience_scope = 'module' THEN
    v_module_id := (NEW.rich_content ->> 'module_id')::uuid;
    IF v_module_id IS NULL THEN
      RAISE EXCEPTION 'ANNOUNCEMENT_MODULE_ID_MISSING: audience_scope=module requires rich_content.module_id (announcement %)', NEW.id;
    END IF;
  ELSIF NEW.audience_scope = 'course' AND NEW.course_id IS NULL THEN
    RAISE EXCEPTION 'ANNOUNCEMENT_COURSE_ID_MISSING: audience_scope=course requires course_id (announcement %)', NEW.id;
  ELSIF NEW.audience_scope = 'cohort' AND NEW.cohort_id IS NULL THEN
    RAISE EXCEPTION 'ANNOUNCEMENT_COHORT_ID_MISSING: audience_scope=cohort requires cohort_id (announcement %)', NEW.id;
  ELSIF NEW.audience_scope = 'specific_users'
        AND (NEW.target_user_ids IS NULL OR cardinality(NEW.target_user_ids) = 0) THEN
    RAISE EXCEPTION 'ANNOUNCEMENT_TARGETS_EMPTY: audience_scope=specific_users requires non-empty target_user_ids (announcement %)', NEW.id;
  END IF;

  INSERT INTO lms.notification_queue (
    tenant_id, user_id, notification_type, channel, subject, body,
    payload, priority, scheduled_for)
  SELECT DISTINCT
    NEW.tenant_id, a.uid, 'announcement', 'in_app', NEW.title,
    left(coalesce(NEW.body, ''), 1000),
    jsonb_build_object('announcement_id', NEW.id, 'course_id', NEW.course_id,
                       'cohort_id', NEW.cohort_id, 'audience_scope', NEW.audience_scope),
    'normal', now()
  FROM (
    SELECT unnest(NEW.target_user_ids) AS uid
    WHERE NEW.target_user_ids IS NOT NULL AND cardinality(NEW.target_user_ids) > 0
    UNION
    SELECT e.learner_user_id
    FROM lms.enrollments e
    WHERE NEW.audience_scope = 'course' AND NEW.course_id IS NOT NULL
      AND e.tenant_id = NEW.tenant_id AND e.course_id = NEW.course_id
      AND e.status NOT IN ('dropped', 'failed', 'transferred')
    UNION
    SELECT cm.learner_user_id
    FROM lms.cohort_members cm
    WHERE NEW.audience_scope = 'cohort' AND NEW.cohort_id IS NOT NULL
      AND cm.tenant_id = NEW.tenant_id AND cm.cohort_id = NEW.cohort_id
    UNION
    SELECT lr.user_id
    FROM lms.lms_roles lr
    WHERE NEW.audience_scope = 'all_tenant'
      AND lr.tenant_id = NEW.tenant_id AND lr.status = 'active'
    UNION
    SELECT mp.learner_user_id
    FROM lms.module_progress mp
    WHERE NEW.audience_scope = 'module' AND v_module_id IS NOT NULL
      AND mp.tenant_id = NEW.tenant_id AND mp.module_id = v_module_id
  ) a
  WHERE NOT EXISTS (
    SELECT 1 FROM lms.notification_queue nq
    WHERE nq.tenant_id = NEW.tenant_id
      AND nq.user_id = a.uid
      AND nq.notification_type = 'announcement'
      AND nq.payload ->> 'announcement_id' = NEW.id::text);
  RETURN NULL;
END;
$$;


ALTER FUNCTION "lms"."fn_announcement_fanout_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."fn_course_completion_issue_credentials"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_def      record;
  v_cred_id  uuid;
  v_first_id uuid := NULL;
BEGIN
  FOR v_def IN
    SELECT * FROM lms.credential_definitions
    WHERE tenant_id = NEW.tenant_id
      AND course_id = NEW.course_id
      AND is_active
    ORDER BY created_at
  LOOP
    IF EXISTS (
      SELECT 1 FROM lms.credentials c
      WHERE c.tenant_id = NEW.tenant_id
        AND c.learner_user_id = NEW.learner_user_id
        AND c.credential_definition_id = v_def.id
        AND c.enrollment_id = NEW.enrollment_id
        AND c.revoked_at IS NULL) THEN
      CONTINUE;  -- already issued for this enrollment: state unchanged by design
    END IF;

    INSERT INTO lms.credentials (
      tenant_id, learner_user_id, course_id, enrollment_id,
      credential_type, title, description, issuer_name,
      issue_date, expiry_date, verification_code,
      credential_definition_id, metadata)
    VALUES (
      NEW.tenant_id, NEW.learner_user_id, NEW.course_id, NEW.enrollment_id,
      v_def.credential_type, v_def.title, v_def.description, v_def.issuing_authority,
      CURRENT_DATE,
      CASE WHEN v_def.validity_months IS NOT NULL
           THEN (CURRENT_DATE + make_interval(months => v_def.validity_months))::date
           ELSE NULL END,
      'LC-' || upper(encode(gen_random_bytes(16), 'hex')),
      v_def.id,
      jsonb_build_object('source', 'course_completion_trigger',
                         'completion_id', NEW.id,
                         'grants_software_access', v_def.grants_software_access,
                         'software_access_tier', v_def.software_access_tier,
                         'state_board_recognized', v_def.is_state_board_recognized))
    RETURNING id INTO v_cred_id;

    IF v_first_id IS NULL THEN v_first_id := v_cred_id; END IF;
  END LOOP;

  IF v_first_id IS NOT NULL THEN
    UPDATE lms.course_completions
       SET credential_id = v_first_id, certificate_issued = true
     WHERE id = NEW.id;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "lms"."fn_course_completion_issue_credentials"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."fn_course_completion_skill_signoffs"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
BEGIN
  INSERT INTO lms.skill_signoffs (
    tenant_id, learner_user_id, skill_id, course_id, enrollment_id,
    signoff_level, signoff_method, status, verification_kind,
    approval_authority, evidence_type, verified_at, metadata)
  SELECT
    NEW.tenant_id, NEW.learner_user_id, t.skill_id, NEW.course_id, NEW.enrollment_id,
    t.target_level, 'auto_on_completion', 'approved', 'course_linked',
    'automated', 'none', now(),
    jsonb_build_object('source', 'course_completion_trigger',
                       'completion_id', NEW.id,
                       'assessment_required', t.assessment_required)
  FROM lms.course_skill_targets t
  WHERE t.tenant_id = NEW.tenant_id
    AND t.course_id = NEW.course_id
    AND t.target_level IN ('introduced', 'practiced', 'mastered')  -- signoff CHECK domain
    AND NOT EXISTS (
      SELECT 1 FROM lms.skill_signoffs s
      WHERE s.tenant_id       = NEW.tenant_id
        AND s.learner_user_id = NEW.learner_user_id
        AND s.skill_id        = t.skill_id
        AND s.course_id       = NEW.course_id
        AND s.status          = 'approved');
  RETURN NULL;
END;
$$;


ALTER FUNCTION "lms"."fn_course_completion_skill_signoffs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."fn_enrollment_assign_lms_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
BEGIN
  INSERT INTO lms.lms_roles (tenant_id, user_id, role, assigned_by, metadata)
  VALUES (
    NEW.tenant_id, NEW.learner_user_id, 'learner', NEW.learner_user_id,
    jsonb_build_object('source', 'enrollment_trigger', 'enrollment_id', NEW.id,
                       'delivery_mode', NEW.delivery_mode)
  )
  ON CONFLICT (tenant_id, user_id) DO UPDATE
    SET status       = 'active',
        revoked_at   = NULL,
        revoke_reason = NULL,
        metadata     = lms.lms_roles.metadata
                       || jsonb_build_object('reactivated_by_enrollment', NEW.id,
                                             'reactivated_at', now())
    WHERE lms.lms_roles.role = 'learner'
      AND lms.lms_roles.status = 'revoked';
  RETURN NULL;
END;
$$;


ALTER FUNCTION "lms"."fn_enrollment_assign_lms_role"() OWNER TO "postgres";


