CREATE OR REPLACE FUNCTION "lms"."maintain_open_badge_assertion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.verification_code IS NULL THEN
        NEW.verification_code = 'LEASHED-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
    END IF;
    NEW.open_badge_json = lms.build_open_badge_json(NEW.id);
    RETURN NEW;
END;
$$;


ALTER FUNCTION "lms"."maintain_open_badge_assertion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."protect_verified_clock_hours"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
    BEGIN
      IF TG_OP = 'DELETE' THEN
        IF OLD.verified_at IS NOT NULL OR OLD.verification_status = 'verified' THEN
          RAISE EXCEPTION 'Audit Violation: Verified clock-hour ledger records are immutable and cannot be deleted. Void the entry instead.';
        END IF;
        RETURN OLD;
      ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.verified_at IS NOT NULL AND OLD.verification_status = 'verified' THEN
          -- Only allow voiding via explicit supersession fields
          IF (OLD.computed_minutes != NEW.computed_minutes OR OLD.verified_minutes != NEW.verified_minutes OR OLD.learner_user_id != NEW.learner_user_id OR OLD.course_id != NEW.course_id) THEN
            RAISE EXCEPTION 'Audit Violation: Verified minutes and core assignment attributes are immutable on clock_hour_ledger.';
          END IF;
        END IF;
        RETURN NEW;
      END IF;
      RETURN NULL;
    END;
    $$;


ALTER FUNCTION "lms"."protect_verified_clock_hours"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."rag_hybrid_search"("p_tenant_id" "uuid", "p_query_text" "text", "p_query_embedding" "public"."vector", "p_course_id" "uuid" DEFAULT NULL::"uuid", "p_module_id" "uuid" DEFAULT NULL::"uuid", "p_pathway_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 10, "p_semantic_weight" double precision DEFAULT 0.7, "p_keyword_weight" double precision DEFAULT 0.3) RETURNS TABLE("chunk_id" "uuid", "document_id" "uuid", "content" "text", "combined_score" double precision, "semantic_score" double precision, "keyword_score" double precision, "page_number" integer, "section_heading" "text", "chunk_metadata" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
    WITH semantic AS (
        SELECT
            c.id AS chunk_id,
            c.document_id,
            c.content,
            1 - (c.embedding <=> p_query_embedding) AS semantic_score,
            c.page_number,
            c.section_heading,
            c.chunk_metadata
        FROM lms.ai_rag_chunks c
        JOIN lms.ai_rag_documents d ON c.document_id = d.id
        WHERE c.tenant_id = p_tenant_id
          AND d.tenant_id = p_tenant_id
          AND c.embedding IS NOT NULL
          AND (p_course_id IS NULL OR c.course_id = p_course_id OR d.course_id = p_course_id)
          AND (p_module_id IS NULL OR c.module_id = p_module_id)
          AND (p_pathway_id IS NULL OR d.pathway_id = p_pathway_id)
        ORDER BY c.embedding <=> p_query_embedding
        LIMIT p_limit * 3
    ),
    keyword AS (
        SELECT
            c.id AS chunk_id,
            c.document_id,
            c.content,
            ts_rank_cd(to_tsvector('english', c.content), plainto_tsquery('english', p_query_text)) AS keyword_score,
            c.page_number,
            c.section_heading,
            c.chunk_metadata
        FROM lms.ai_rag_chunks c
        JOIN lms.ai_rag_documents d ON c.document_id = d.id
        WHERE c.tenant_id = p_tenant_id
          AND d.tenant_id = p_tenant_id
          AND to_tsvector('english', c.content) @@ plainto_tsquery('english', p_query_text)
          AND (p_course_id IS NULL OR c.course_id = p_course_id OR d.course_id = p_course_id)
          AND (p_module_id IS NULL OR c.module_id = p_module_id)
          AND (p_pathway_id IS NULL OR d.pathway_id = p_pathway_id)
        ORDER BY keyword_score DESC
        LIMIT p_limit * 3
    )
    SELECT
        COALESCE(s.chunk_id, k.chunk_id) AS chunk_id,
        COALESCE(s.document_id, k.document_id) AS document_id,
        COALESCE(s.content, k.content) AS content,
        (p_semantic_weight * COALESCE(s.semantic_score, 0) + p_keyword_weight * COALESCE(k.keyword_score, 0)) AS combined_score,
        COALESCE(s.semantic_score, 0) AS semantic_score,
        COALESCE(k.keyword_score, 0) AS keyword_score,
        COALESCE(s.page_number, k.page_number) AS page_number,
        COALESCE(s.section_heading, k.section_heading) AS section_heading,
        COALESCE(s.chunk_metadata, k.chunk_metadata) AS chunk_metadata
    FROM semantic s
    FULL OUTER JOIN keyword k ON s.chunk_id = k.chunk_id
    ORDER BY combined_score DESC
    LIMIT p_limit;
$$;


ALTER FUNCTION "lms"."rag_hybrid_search"("p_tenant_id" "uuid", "p_query_text" "text", "p_query_embedding" "public"."vector", "p_course_id" "uuid", "p_module_id" "uuid", "p_pathway_id" "uuid", "p_limit" integer, "p_semantic_weight" double precision, "p_keyword_weight" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."rag_search"("p_tenant_id" "uuid", "p_query" "text", "p_query_embedding" "public"."vector" DEFAULT NULL::"public"."vector", "p_course_id" "uuid" DEFAULT NULL::"uuid", "p_module_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 10, "p_include_non_learner_facing" boolean DEFAULT false, "p_rrf_k" integer DEFAULT 60) RETURNS TABLE("chunk_id" "uuid", "document_id" "uuid", "content" "text", "score" double precision, "vector_rank" integer, "text_rank" integer, "source_code" "text", "rag_role" "text", "safety_flag" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_allow_restricted boolean;
BEGIN
    -- Do not trust a caller-supplied tenant id.
    IF NOT (lms.is_tenant_member(p_tenant_id) OR lms.is_platform_admin()) THEN
        RAISE EXCEPTION 'Not a member of tenant %', p_tenant_id
            USING ERRCODE = '42501';
    END IF;

    v_allow_restricted := p_include_non_learner_facing
        AND (lms.is_instructor(p_tenant_id)
             OR lms.is_lms_admin(p_tenant_id)
             OR lms.is_platform_admin());

    RETURN QUERY
    WITH scoped AS (
        SELECT c.id, c.document_id, c.content, c.embedding, d.learner_facing,
               d.source_id
        FROM lms.ai_rag_chunks c
        JOIN lms.ai_rag_documents d
          ON d.tenant_id = c.tenant_id AND d.id = c.document_id
        WHERE c.tenant_id = p_tenant_id
          AND (p_course_id IS NULL OR c.course_id = p_course_id)
          AND (p_module_id IS NULL OR c.module_id = p_module_id)
          AND (v_allow_restricted OR d.learner_facing = true)
    ),
    vec AS (
        SELECT s.id,
               row_number() OVER (ORDER BY s.embedding <=> p_query_embedding) AS rnk
        FROM scoped s
        WHERE p_query_embedding IS NOT NULL
          AND s.embedding IS NOT NULL
        ORDER BY s.embedding <=> p_query_embedding
        LIMIT GREATEST(p_limit * 5, 50)
    ),
    fts AS (
        SELECT s.id,
               row_number() OVER (
                   ORDER BY ts_rank_cd(
                       to_tsvector('english', s.content),
                       plainto_tsquery('english', p_query)) DESC
               ) AS rnk
        FROM scoped s
        WHERE p_query IS NOT NULL
          AND to_tsvector('english', s.content) @@ plainto_tsquery('english', p_query)
        LIMIT GREATEST(p_limit * 5, 50)
    ),
    fused AS (
        SELECT
            coalesce(v.id, f.id) AS id,
            coalesce(1.0 / (p_rrf_k + v.rnk), 0)
          + coalesce(1.0 / (p_rrf_k + f.rnk), 0) AS rrf,
            v.rnk AS vrank,
            f.rnk AS frank
        FROM vec v
        FULL OUTER JOIN fts f ON f.id = v.id
    )
    SELECT
        s.id,
        s.document_id,
        s.content,
        fu.rrf::double precision,
        fu.vrank::integer,
        fu.frank::integer,
        rs.source_code,
        rs.rag_role,
        coalesce(rs.safety_flag, false)
    FROM fused fu
    JOIN scoped s ON s.id = fu.id
    LEFT JOIN lms.rag_sources rs
           ON rs.tenant_id = p_tenant_id AND rs.id = s.source_id
    ORDER BY fu.rrf DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "lms"."rag_search"("p_tenant_id" "uuid", "p_query" "text", "p_query_embedding" "public"."vector", "p_course_id" "uuid", "p_module_id" "uuid", "p_limit" integer, "p_include_non_learner_facing" boolean, "p_rrf_k" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "lms"."rag_search"("p_tenant_id" "uuid", "p_query" "text", "p_query_embedding" "public"."vector", "p_course_id" "uuid", "p_module_id" "uuid", "p_limit" integer, "p_include_non_learner_facing" boolean, "p_rrf_k" integer) IS 'Hybrid retrieval: reciprocal rank fusion over HNSW vector ANN and GIN full-text. Pass p_query_embedding NULL for keyword-only. Enforces tenant membership and Ingestion Rule 4 (system-training sources are never learner-facing).';



CREATE OR REPLACE FUNCTION "lms"."rag_vector_search"("p_tenant_id" "uuid", "p_query_embedding" "public"."vector", "p_course_id" "uuid" DEFAULT NULL::"uuid", "p_module_id" "uuid" DEFAULT NULL::"uuid", "p_pathway_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 10, "p_similarity_threshold" double precision DEFAULT 0.7) RETURNS TABLE("chunk_id" "uuid", "document_id" "uuid", "content" "text", "similarity" double precision, "page_number" integer, "section_heading" "text", "chunk_metadata" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
    SELECT
        c.id AS chunk_id,
        c.document_id,
        c.content,
        1 - (c.embedding <=> p_query_embedding) AS similarity,
        c.page_number,
        c.section_heading,
        c.chunk_metadata
    FROM lms.ai_rag_chunks c
    JOIN lms.ai_rag_documents d ON c.document_id = d.id
    WHERE c.tenant_id = p_tenant_id
      AND d.tenant_id = p_tenant_id
      AND c.embedding IS NOT NULL
      AND (1 - (c.embedding <=> p_query_embedding)) >= p_similarity_threshold
      AND (p_course_id IS NULL OR c.course_id = p_course_id OR d.course_id = p_course_id)
      AND (p_module_id IS NULL OR c.module_id = p_module_id)
      AND (p_pathway_id IS NULL OR d.pathway_id = p_pathway_id)
    ORDER BY c.embedding <=> p_query_embedding
    LIMIT p_limit;
$$;


ALTER FUNCTION "lms"."rag_vector_search"("p_tenant_id" "uuid", "p_query_embedding" "public"."vector", "p_course_id" "uuid", "p_module_id" "uuid", "p_pathway_id" "uuid", "p_limit" integer, "p_similarity_threshold" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."recompute_skill_progress"("p_tenant_id" "uuid", "p_learner_user_id" "uuid", "p_skill_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_signoff   RECORD;
    v_event     RECORD;
    v_level     text := NULL;
    v_at        timestamptz := NULL;
    v_by        uuid := NULL;
    v_source    text := NULL;
    v_blocked   boolean := false;
BEGIN
    -- An automatic fail or a revocation blocks mastery outright.
    SELECT true INTO v_blocked
    FROM lms.skill_signoffs s
    WHERE s.tenant_id = p_tenant_id
      AND s.learner_user_id = p_learner_user_id
      AND s.skill_id = p_skill_id
      AND (s.automatic_fail = true OR s.status = 'revoked')
      AND s.verified_at >= coalesce((
            SELECT max(s2.verified_at) FROM lms.skill_signoffs s2
            WHERE s2.tenant_id = p_tenant_id
              AND s2.learner_user_id = p_learner_user_id
              AND s2.skill_id = p_skill_id
              AND s2.status = 'approved'
              AND s2.automatic_fail = false
          ), '-infinity'::timestamptz)
    LIMIT 1;

    -- Highest approved signoff level wins; ties broken by most recent.
    SELECT s.signoff_level, s.verified_at, s.verified_by
      INTO v_signoff
    FROM lms.skill_signoffs s
    WHERE s.tenant_id = p_tenant_id
      AND s.learner_user_id = p_learner_user_id
      AND s.skill_id = p_skill_id
      AND s.status = 'approved'
      AND s.automatic_fail = false
    ORDER BY lms.competency_rank(s.signoff_level) DESC, s.verified_at DESC
    LIMIT 1;

    -- Only 'approved' events count. The old summary view read pending rows
    -- as current state.
    SELECT e.signoff_level, e.created_at, e.signoff_user_id
      INTO v_event
    FROM lms.skill_signoff_events e
    WHERE e.tenant_id = p_tenant_id
      AND e.learner_user_id = p_learner_user_id
      AND e.skill_id = p_skill_id
      AND e.status = 'approved'
    ORDER BY lms.competency_rank(e.signoff_level) DESC, e.created_at DESC
    LIMIT 1;

    IF v_signoff.signoff_level IS NOT NULL
       AND (v_event.signoff_level IS NULL
            OR lms.competency_rank(v_signoff.signoff_level)
               >= lms.competency_rank(v_event.signoff_level)) THEN
        v_level  := v_signoff.signoff_level;
        v_at     := v_signoff.verified_at;
        v_by     := v_signoff.verified_by;
        v_source := 'signoff';
    ELSIF v_event.signoff_level IS NOT NULL THEN
        v_level  := v_event.signoff_level;
        v_at     := v_event.created_at;
        v_by     := v_event.signoff_user_id;
        v_source := 'event';
    END IF;

    IF v_blocked THEN
        v_level := NULL; v_at := NULL; v_by := NULL; v_source := NULL;
    END IF;

    INSERT INTO lms.skill_progress AS sp (
        tenant_id, learner_user_id, skill_id,
        competency_level, signed_off_level, is_signed_off,
        signed_off_at, signed_off_by, signoff_source,
        progress_percentage, last_recomputed_at, updated_at
    )
    VALUES (
        p_tenant_id, p_learner_user_id, p_skill_id,
        coalesce(v_level, 'not_started'), v_level, (v_level IS NOT NULL),
        v_at, v_by, v_source,
        CASE lms.competency_rank(coalesce(v_level,'not_started'))
             WHEN 3 THEN 100 WHEN 2 THEN 66 WHEN 1 THEN 33 ELSE 0 END,
        now(), now()
    )
    ON CONFLICT (tenant_id, learner_user_id, skill_id) DO UPDATE
    SET competency_level = CASE
            -- Never regress a level earned through coursework unless blocked.
            WHEN v_blocked THEN sp.competency_level
            WHEN lms.competency_rank(coalesce(v_level,'not_started'))
                 > lms.competency_rank(sp.competency_level)
                THEN coalesce(v_level, sp.competency_level)
            ELSE sp.competency_level
        END,
        signed_off_level   = v_level,
        is_signed_off      = (v_level IS NOT NULL),
        signed_off_at      = v_at,
        signed_off_by      = v_by,
        signoff_source     = v_source,
        last_recomputed_at = now(),
        updated_at         = now();
END;
$$;


ALTER FUNCTION "lms"."recompute_skill_progress"("p_tenant_id" "uuid", "p_learner_user_id" "uuid", "p_skill_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."reconcile_learner_points"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_points_delta integer;
    v_learner uuid;
    v_tenant uuid;
BEGIN
    v_tenant := COALESCE(NEW.tenant_id, OLD.tenant_id);
    v_learner := COALESCE(NEW.learner_user_id, OLD.learner_user_id);
    v_points_delta := COALESCE(NEW.points, 0) - COALESCE(OLD.points, 0);

    IF TG_OP = 'DELETE' THEN
        v_points_delta := -OLD.points;
    END IF;

    -- Upssert learner_points with correct total
    INSERT INTO lms.learner_points (tenant_id, learner_user_id, total_points, points_this_week, points_this_month, updated_at)
    VALUES (v_tenant, v_learner, v_points_delta, 0, 0, now())
    ON CONFLICT (tenant_id, learner_user_id)
    DO UPDATE SET
        total_points = learner_points.total_points + v_points_delta,
        updated_at = now();
    RETURN NEW;
END;
$$;


ALTER FUNCTION "lms"."reconcile_learner_points"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."request_platform_conversion"("p_tenant_id" "uuid", "p_learner_user_id" "uuid", "p_credential_id" "uuid", "p_notes" "text" DEFAULT NULL::"text", OUT "o_conversion_id" "uuid", OUT "o_license_grant_id" "uuid", OUT "o_created" boolean) RETURNS "record"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_cred lms.credentials%ROWTYPE;
  v_def  lms.credential_definitions%ROWTYPE;
BEGIN
  SELECT * INTO v_cred
  FROM lms.credentials
  WHERE id = p_credential_id
    AND tenant_id = p_tenant_id
    AND learner_user_id = p_learner_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSION_CREDENTIAL_NOT_FOUND: credential % does not exist for learner % in tenant % (loud gate: has-a-credential -> has-platform-access)',
      p_credential_id, p_learner_user_id, p_tenant_id;
  END IF;
  IF v_cred.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'CONVERSION_CREDENTIAL_REVOKED: credential % is revoked and cannot grant platform access', p_credential_id;
  END IF;

  SELECT id INTO o_conversion_id
  FROM lms.conversion_records
  WHERE tenant_id = p_tenant_id
    AND origin_reference_id = p_credential_id::text
    AND conversion_status NOT IN ('abandoned', 'reversed')
  ORDER BY created_at DESC
  LIMIT 1;
  IF o_conversion_id IS NOT NULL THEN
    o_created := false;   -- explicit, not silent: caller sees created=false
    RETURN;
  END IF;

  SELECT * INTO v_def
  FROM lms.credential_definitions
  WHERE id = v_cred.credential_definition_id;

  INSERT INTO lms.conversion_records (
    tenant_id, learner_user_id, origin_entity, origin_reference_id,
    conversion_status, notes, metadata)
  VALUES (
    p_tenant_id, p_learner_user_id, 'learner_self_enroll', p_credential_id::text,
    'learner_created', p_notes,
    jsonb_build_object('credential_id', p_credential_id,
                       'credential_definition_id', v_cred.credential_definition_id,
                       'credential_title', v_cred.title,
                       'grants_software_access', COALESCE(v_def.grants_software_access, false)))
  RETURNING id INTO o_conversion_id;

  o_license_grant_id := NULL;
  IF COALESCE(v_def.grants_software_access, false) THEN
    INSERT INTO lms.free_license_grants (
      tenant_id, learner_user_id, course_id, granted_by, license_type, metadata)
    VALUES (
      p_tenant_id, p_learner_user_id, v_cred.course_id, p_learner_user_id, 'free',
      jsonb_build_object('source', 'platform_conversion',
                         'conversion_id', o_conversion_id,
                         'credential_id', p_credential_id,
                         'software_access_tier', v_def.software_access_tier))
    RETURNING id INTO o_license_grant_id;
  END IF;

  INSERT INTO lms.crm_sync_queue (
    tenant_id, sync_direction, entity_type, entity_id, sync_data)
  VALUES (
    p_tenant_id, 'lms_to_crm', 'crm_customer_stub', o_conversion_id,
    jsonb_build_object('conversion_id', o_conversion_id,
                       'learner_user_id', p_learner_user_id,
                       'credential_id', p_credential_id,
                       'origin', 'lms_platform_bridge'));

  INSERT INTO lms.commerce_sync_queue (
    tenant_id, sync_direction, entity_type, entity_id, sync_data)
  VALUES (
    p_tenant_id, 'lms_to_commerce', 'salon_branch_stub', o_conversion_id,
    jsonb_build_object('conversion_id', o_conversion_id,
                       'learner_user_id', p_learner_user_id,
                       'credential_id', p_credential_id,
                       'origin', 'lms_platform_bridge'));

  o_created := true;
END;
$$;


ALTER FUNCTION "lms"."request_platform_conversion"("p_tenant_id" "uuid", "p_learner_user_id" "uuid", "p_credential_id" "uuid", "p_notes" "text", OUT "o_conversion_id" "uuid", OUT "o_license_grant_id" "uuid", OUT "o_created" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "lms"."sync_course_pathway"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
BEGIN
    -- When a pathway_courses row is inserted/updated, sync the course's pathway_id
    IF (TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.pathway_id IS DISTINCT FROM OLD.pathway_id)) THEN
        UPDATE lms.courses
        SET pathway_id = NEW.pathway_id,
            updated_at = now()
        WHERE id = NEW.course_id
          AND tenant_id = NEW.tenant_id
          AND pathway_id IS DISTINCT FROM NEW.pathway_id;
    END IF;
    RETURN NEW;
END;
$$;


