CREATE OR REPLACE FUNCTION "public"."convert_purchase_order_to_bill"("p_tenant_id" "uuid", "p_po_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_po        purchase_orders%rowtype;
  v_bill_id   uuid;
  v_bill_num  text;
  v_items     jsonb := '[]'::jsonb;
  v_item      purchase_order_items%rowtype;
begin
  select * into v_po from purchase_orders where id = p_po_id and tenant_id = p_tenant_id;
  if not found then raise exception 'Purchase order not found'; end if;
  if v_po.converted_bill_id is not null then
    return v_po.converted_bill_id;
  end if;

  v_bill_num := replace(v_po.number, 'PO-', 'BILL-');

  -- build items jsonb from PO items
  for v_item in select * from purchase_order_items where purchase_order_id = p_po_id loop
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'product_id', v_item.product_id,
      'inventory_item_id', v_item.inventory_item_id,
      'account_id', v_item.account_id,
      'tax_id', v_item.tax_id,
      'description', v_item.description,
      'quantity', v_item.quantity,
      'unit_price', v_item.unit_price,
      'discount', v_item.discount,
      'position', v_item.position
    ));
  end loop;

  -- create the bill
  v_bill_id := create_bill(
    p_tenant_id := p_tenant_id,
    p_number := v_bill_num,
    p_vendor_id := v_po.vendor_id,
    p_issue_date := v_po.issue_date,
    p_due_date := coalesce(v_po.expected_date, v_po.issue_date + 30),
    p_currency := v_po.currency,
    p_items := v_items,
    p_notes := v_po.notes,
    p_ap_account_id := null
  );

  -- mark PO as converted
  update purchase_orders
     set converted_bill_id = v_bill_id, status = 'closed', updated_at = now()
   where id = p_po_id;

  return v_bill_id;
end;
$$;


ALTER FUNCTION "public"."convert_purchase_order_to_bill"("p_tenant_id" "uuid", "p_po_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_sales_order_to_invoice"("p_tenant_id" "uuid", "p_so_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_so        sales_orders%rowtype;
  v_inv_id    text;
  v_inv_number text;
  v_item      sales_order_items%rowtype;
  v_ar_acct   uuid;
begin
  select * into v_so from sales_orders where id = p_so_id and tenant_id = p_tenant_id;
  if not found then raise exception 'Sales order not found'; end if;
  if v_so.converted_invoice_id is not null then
    return v_so.converted_invoice_id;
  end if;

  -- find default AR account (1100)
  select id into v_ar_acct from chart_of_accounts
   where tenant_id = p_tenant_id and code = '1100' limit 1;
  if v_ar_acct is null then
    raise exception 'No Accounts Receivable account found. Seed standard chart of accounts.';
  end if;

  -- generate invoice number
  select 'INV-' || to_char(now(), 'YYYY') || '-' || lpad((count(*) + 1)::text, 4, '0')
    into v_inv_number
    from invoices where tenant_id = p_tenant_id;

  -- insert into existing invoices table (text PK, camelCase columns)
  insert into invoices (
    "customerId", number, status, subtotal, "balanceDue", total,
    "createdAt", "updatedAt", tenant_id, ar_account_id, currency, amount_paid
  ) values (
    v_so.customer_id, v_inv_number, 'OPEN',
    v_so.subtotal::text, v_so.total::text, v_so.total::text,
    now(), now(), p_tenant_id, v_ar_acct, v_so.currency, 0
  )
  returning id into v_inv_id;

  -- copy items into invoice_items
  for v_item in select * from sales_order_items where sales_order_id = p_so_id loop
    insert into invoice_items ("invoiceId", description, quantity, "unitPrice", "totalPrice", "createdAt", tenant_id)
    values (v_inv_id, v_item.description, v_item.quantity::int, v_item.unit_price::text,
            (v_item.quantity * v_item.unit_price)::text, now(), p_tenant_id);
  end loop;

  -- mark SO as converted
  update sales_orders
     set converted_invoice_id = v_inv_id, status = 'closed', updated_at = now()
   where id = p_so_id;

  return v_inv_id;
end;
$$;


ALTER FUNCTION "public"."convert_sales_order_to_invoice"("p_tenant_id" "uuid", "p_so_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_bill"("p_tenant_id" "uuid", "p_number" "text", "p_vendor_id" "text", "p_issue_date" "date", "p_due_date" "date" DEFAULT NULL::"date", "p_currency" "text" DEFAULT 'USD'::"text", "p_items" "jsonb" DEFAULT NULL::"jsonb", "p_notes" "text" DEFAULT NULL::"text", "p_ap_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_bill_id     uuid;
  v_ap_acct     uuid := p_ap_account_id;
  v_subtotal    numeric(18,4) := 0;
  v_tax_total   numeric(18,4) := 0;
  v_total       numeric(18,4) := 0;
  v_item        jsonb;
  v_line_amt    numeric(18,4);
  v_tax_rate    numeric(6,4);
  v_lines       jsonb := '[]'::jsonb;
  v_journal_id  uuid;
begin
  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'No bill items provided';
  end if;

  -- find default AP account (2000)
  if v_ap_acct is null then
    select id into v_ap_acct from chart_of_accounts
     where tenant_id = p_tenant_id and code = '2000' limit 1;
  end if;
  if v_ap_acct is null then
    raise exception 'No Accounts Payable account found. Seed standard chart of accounts.';
  end if;

  -- insert bill header
  insert into bills (tenant_id, number, vendor_id, issue_date, due_date, currency, status,
                     subtotal, tax_total, total, ap_account_id, notes)
  values (p_tenant_id, p_number, p_vendor_id, p_issue_date, p_due_date, p_currency, 'received',
          0, 0, 0, v_ap_acct, p_notes)
  returning id into v_bill_id;

  -- insert items + build journal lines
  for v_item in select jsonb_array_elements(p_items) loop
    v_line_amt := coalesce((v_item->>'quantity')::numeric, 1) * coalesce((v_item->>'unit_price')::numeric, 0)
                  - coalesce((v_item->>'discount')::numeric, 0);
    v_subtotal := v_subtotal + v_line_amt;

    -- tax per line
    v_tax_rate := 0;
    if v_item ? 'tax_id' and (v_item->>'tax_id') is not null then
      select rate into v_tax_rate from taxes where id = (v_item->>'tax_id')::uuid;
    end if;
    v_tax_total := v_tax_total + (v_line_amt * v_tax_rate);

    insert into bill_items (bill_id, product_id, inventory_item_id, account_id, tax_id,
                            description, quantity, unit_price, discount, position)
    values (v_bill_id,
            nullif(v_item->>'product_id','')::text,
            nullif(v_item->>'inventory_item_id','')::text,
            (v_item->>'account_id')::uuid,
            nullif(v_item->>'tax_id','')::uuid,
            v_item->>'description',
            coalesce((v_item->>'quantity')::numeric, 1),
            coalesce((v_item->>'unit_price')::numeric, 0),
            coalesce((v_item->>'discount')::numeric, 0),
            coalesce((v_item->>'position')::int, 0));

    -- DR Expense
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'account_id', (v_item->>'account_id')::uuid,
      'debit', v_line_amt, 'credit', 0,
      'description', coalesce(v_item->>'description', 'Bill ' || p_number)
    ));

    -- If inventory_item_id is set, apply stock movement (receive inventory)
    if v_item ? 'inventory_item_id' and (v_item->>'inventory_item_id') is not null then
      perform apply_stock_movement(
        p_tenant_id := p_tenant_id,
        p_inventory_item_id := (v_item->>'inventory_item_id')::text,
        p_date := p_issue_date,
        p_type := 'purchase',
        p_quantity := coalesce((v_item->>'quantity')::numeric, 1),
        p_unit_cost := coalesce((v_item->>'unit_price')::numeric, 0),
        p_source := 'bill',
        p_source_id := v_bill_id::text,
        p_reference := p_number
      );
    end if;
  end loop;

  v_total := v_subtotal + v_tax_total;

  -- CR AP (full)
  v_lines := v_lines || jsonb_build_array(jsonb_build_object(
    'account_id', v_ap_acct,
    'debit', 0, 'credit', v_total,
    'description', 'AP — ' || p_number
  ));

  -- DR Tax line (if any tax)
  if v_tax_total > 0 then
    declare
      v_tax_acct uuid;
    begin
      select id into v_tax_acct from chart_of_accounts
       where tenant_id = p_tenant_id and code = '2100' limit 1;
      -- We already added tax to AP credit (full v_total), so add a DR to offset tax expense:
      -- Actually proper entry: DR Expense (net), DR Tax, CR AP (gross).
      -- Easier: rebuild v_lines — but for now, post the tax as a separate adjusting entry.
      -- For simplicity here: subtract tax from expense lines and post tax DR separately.
      -- (Already added full v_subtotal as DR expense, so we just add DR Tax as additional line and increase AP credit.)
      v_lines := v_lines || jsonb_build_array(jsonb_build_object(
        'account_id', v_tax_acct,
        'debit', v_tax_total, 'credit', 0,
        'description', 'Sales tax recoverable — ' || p_number
      ));
    end;
  end if;

  -- Post the journal
  v_journal_id := post_journal(
    p_tenant_id := p_tenant_id,
    p_entry_date := p_issue_date,
    p_lines := v_lines,
    p_memo := 'Bill ' || p_number || ' received',
    p_reference := p_number,
    p_source := 'bill',
    p_source_id := v_bill_id::text,
    p_currency := p_currency
  );

  -- link bill to journal + update totals
  update bills
     set subtotal = v_subtotal,
         tax_total = v_tax_total,
         total = v_total,
         journal_id = v_journal_id
   where id = v_bill_id;

  return v_bill_id;
end;
$$;


ALTER FUNCTION "public"."create_bill"("p_tenant_id" "uuid", "p_number" "text", "p_vendor_id" "text", "p_issue_date" "date", "p_due_date" "date", "p_currency" "text", "p_items" "jsonb", "p_notes" "text", "p_ap_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_purchase_order"("p_tenant_id" "uuid", "p_number" "text", "p_vendor_id" "text", "p_issue_date" "date", "p_expected_date" "date" DEFAULT NULL::"date", "p_currency" "text" DEFAULT 'USD'::"text", "p_items" "jsonb" DEFAULT NULL::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_po_id      uuid;
  v_item       jsonb;
  v_subtotal   numeric(18,4) := 0;
  v_tax_total  numeric(18,4) := 0;
  v_total      numeric(18,4) := 0;
  v_line_amt   numeric(18,4);
  v_tax_rate   numeric(6,4);
begin
  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'No purchase order items provided';
  end if;

  insert into purchase_orders (tenant_id, number, vendor_id, issue_date, expected_date, currency, status, notes)
  values (p_tenant_id, p_number, p_vendor_id, p_issue_date, p_expected_date, p_currency, 'draft', p_notes)
  returning id into v_po_id;

  for v_item in select jsonb_array_elements(p_items) loop
    v_line_amt := coalesce((v_item->>'quantity')::numeric, 1) * coalesce((v_item->>'unit_price')::numeric, 0)
                  - coalesce((v_item->>'discount')::numeric, 0);
    v_subtotal := v_subtotal + v_line_amt;

    v_tax_rate := 0;
    if v_item ? 'tax_id' and (v_item->>'tax_id') is not null then
      select rate into v_tax_rate from taxes where id = (v_item->>'tax_id')::uuid;
    end if;
    v_tax_total := v_tax_total + (v_line_amt * v_tax_rate);

    insert into purchase_order_items (purchase_order_id, product_id, inventory_item_id, account_id, tax_id,
                                       description, quantity, unit_price, discount, position)
    values (v_po_id,
            nullif(v_item->>'product_id','')::text,
            nullif(v_item->>'inventory_item_id','')::text,
            (v_item->>'account_id')::uuid,
            nullif(v_item->>'tax_id','')::uuid,
            v_item->>'description',
            coalesce((v_item->>'quantity')::numeric, 1),
            coalesce((v_item->>'unit_price')::numeric, 0),
            coalesce((v_item->>'discount')::numeric, 0),
            coalesce((v_item->>'position')::int, 0));
  end loop;

  v_total := v_subtotal + v_tax_total;
  update purchase_orders set subtotal = v_subtotal, tax_total = v_tax_total, total = v_total
   where id = v_po_id;

  return v_po_id;
end;
$$;


ALTER FUNCTION "public"."create_purchase_order"("p_tenant_id" "uuid", "p_number" "text", "p_vendor_id" "text", "p_issue_date" "date", "p_expected_date" "date", "p_currency" "text", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_receipt"("p_tenant_id" "uuid", "p_number" "text", "p_receipt_date" "date", "p_amount" numeric, "p_deposit_account_id" "uuid", "p_customer_id" "text" DEFAULT NULL::"text", "p_method" "text" DEFAULT 'cash'::"text", "p_revenue_account_id" "uuid" DEFAULT NULL::"uuid", "p_currency" "text" DEFAULT 'USD'::"text", "p_items" "jsonb" DEFAULT NULL::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_receipt_id    uuid;
  v_rev_acct      uuid := p_revenue_account_id;
  v_tax_acct      uuid;
  v_tax_total     numeric(18,4) := 0;
  v_total         numeric(18,4) := 0;
  v_item          jsonb;
  v_lines         jsonb := '[]'::jsonb;
  v_journal_id    uuid;
begin
  if p_amount <= 0 then raise exception 'Receipt amount must be positive'; end if;

  -- default revenue account (4000)
  if v_rev_acct is null then
    select id into v_rev_acct from chart_of_accounts
     where tenant_id = p_tenant_id and code = '4000' limit 1;
  end if;
  if v_rev_acct is null then
    raise exception 'No Sales Revenue account found. Seed standard chart of accounts.';
  end if;

  insert into receipts (tenant_id, number, customer_id, receipt_date, kind, amount, currency, method,
                        deposit_account_id, revenue_account_id, notes)
  values (p_tenant_id, p_number, p_customer_id, p_receipt_date, 'sale', p_amount, p_currency,
          p_method::payment_method, p_deposit_account_id, v_rev_acct, p_notes)
  returning id into v_receipt_id;

  -- if items provided, build per-line journal entries + decrement inventory
  if p_items is not null and jsonb_array_length(p_items) > 0 then
    for v_item in select jsonb_array_elements(p_items) loop
      declare
        v_qty    numeric(18,4) := coalesce((v_item->>'quantity')::numeric, 1);
        v_price  numeric(18,4) := coalesce((v_item->>'unit_price')::numeric, 0);
        v_amt    numeric(18,4) := v_qty * v_price;
        v_tax_id uuid := nullif(v_item->>'tax_id','')::uuid;
        v_tax_rate numeric(6,4) := 0;
        v_item_acct uuid := (v_item->>'account_id')::uuid;
      begin
        if v_item_acct is null then v_item_acct := v_rev_acct; end if;
        if v_tax_id is not null then
          select rate into v_tax_rate from taxes where id = v_tax_id;
        end if;
        v_tax_total := v_tax_total + (v_amt * v_tax_rate);
        v_total := v_total + v_amt;

        insert into receipt_items (receipt_id, product_id, inventory_item_id, account_id, description, quantity, unit_price, tax_id)
        values (v_receipt_id,
                nullif(v_item->>'product_id','')::text,
                nullif(v_item->>'inventory_item_id','')::text,
                v_item_acct,
                v_item->>'description',
                v_qty, v_price, v_tax_id);

        -- decrement inventory if tracked
        if v_item ? 'inventory_item_id' and (v_item->>'inventory_item_id') is not null then
          perform apply_stock_movement(
            p_tenant_id := p_tenant_id,
            p_inventory_item_id := (v_item->>'inventory_item_id')::text,
            p_date := p_receipt_date,
            p_type := 'sale',
            p_quantity := -v_qty,
            p_unit_cost := 0,
            p_source := 'receipt',
            p_source_id := v_receipt_id::text,
            p_reference := p_number
          );
        end if;
      end;
    end loop;
  else
    -- unitemized receipt — full amount to revenue
    v_total := p_amount;
  end if;

  -- build journal lines: DR deposit / CR revenue / CR tax
  v_lines := v_lines || jsonb_build_array(jsonb_build_object(
    'account_id', p_deposit_account_id, 'debit', p_amount, 'credit', 0,
    'description', 'Receipt ' || p_number
  ));
  v_lines := v_lines || jsonb_build_array(jsonb_build_object(
    'account_id', v_rev_acct, 'debit', 0, 'credit', v_total,
    'description', 'Sales — ' || p_number
  ));
  if v_tax_total > 0 then
    select id into v_tax_acct from chart_of_accounts
     where tenant_id = p_tenant_id and code = '2100' limit 1;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'account_id', v_tax_acct, 'debit', 0, 'credit', v_tax_total,
      'description', 'Sales tax — ' || p_number
    ));
  end if;

  v_journal_id := post_journal(
    p_tenant_id := p_tenant_id,
    p_entry_date := p_receipt_date,
    p_lines := v_lines,
    p_memo := 'Receipt ' || p_number,
    p_reference := p_number,
    p_source := 'receipt',
    p_source_id := v_receipt_id::text,
    p_currency := p_currency
  );

  update receipts set journal_id = v_journal_id where id = v_receipt_id;
  return v_receipt_id;
end;
$$;


ALTER FUNCTION "public"."create_receipt"("p_tenant_id" "uuid", "p_number" "text", "p_receipt_date" "date", "p_amount" numeric, "p_deposit_account_id" "uuid", "p_customer_id" "text", "p_method" "text", "p_revenue_account_id" "uuid", "p_currency" "text", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_sales_order"("p_tenant_id" "uuid", "p_number" "text", "p_customer_id" "text", "p_issue_date" "date", "p_expected_date" "date" DEFAULT NULL::"date", "p_currency" "text" DEFAULT 'USD'::"text", "p_items" "jsonb" DEFAULT NULL::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_so_id      uuid;
  v_item       jsonb;
  v_subtotal   numeric(18,4) := 0;
  v_tax_total  numeric(18,4) := 0;
  v_total      numeric(18,4) := 0;
  v_line_amt   numeric(18,4);
  v_tax_rate   numeric(6,4);
begin
  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'No sales order items provided';
  end if;

  insert into sales_orders (tenant_id, number, customer_id, issue_date, expected_date, currency, status, notes)
  values (p_tenant_id, p_number, p_customer_id, p_issue_date, p_expected_date, p_currency, 'draft', p_notes)
  returning id into v_so_id;

  for v_item in select jsonb_array_elements(p_items) loop
    v_line_amt := coalesce((v_item->>'quantity')::numeric, 1) * coalesce((v_item->>'unit_price')::numeric, 0)
                  - coalesce((v_item->>'discount')::numeric, 0);
    v_subtotal := v_subtotal + v_line_amt;

    v_tax_rate := 0;
    if v_item ? 'tax_id' and (v_item->>'tax_id') is not null then
      select rate into v_tax_rate from taxes where id = (v_item->>'tax_id')::uuid;
    end if;
    v_tax_total := v_tax_total + (v_line_amt * v_tax_rate);

    insert into sales_order_items (sales_order_id, product_id, inventory_item_id, account_id, tax_id,
                                   description, quantity, unit_price, discount, position)
    values (v_so_id,
            nullif(v_item->>'product_id','')::text,
            nullif(v_item->>'inventory_item_id','')::text,
            (v_item->>'account_id')::uuid,
            nullif(v_item->>'tax_id','')::uuid,
            v_item->>'description',
            coalesce((v_item->>'quantity')::numeric, 1),
            coalesce((v_item->>'unit_price')::numeric, 0),
            coalesce((v_item->>'discount')::numeric, 0),
            coalesce((v_item->>'position')::int, 0));
  end loop;

  v_total := v_subtotal + v_tax_total;
  update sales_orders set subtotal = v_subtotal, tax_total = v_tax_total, total = v_total
   where id = v_so_id;

  return v_so_id;
end;
$$;


ALTER FUNCTION "public"."create_sales_order"("p_tenant_id" "uuid", "p_number" "text", "p_customer_id" "text", "p_issue_date" "date", "p_expected_date" "date", "p_currency" "text", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


