CREATE OR REPLACE FUNCTION "public"."trg_seller_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE r RECORD;
BEGIN
  IF NEW.status = 'approved' AND OLD.status <> 'approved' AND NEW.approved_at IS NULL THEN
    UPDATE sellers SET approved_at = now() WHERE id = NEW.id;
  END IF;
  IF OLD.status = 'approved' AND NEW.status <> 'approved' THEN
    UPDATE offers SET status = 'suppressed' WHERE seller_id = NEW.id AND status = 'active';
    FOR r IN SELECT brand_id FROM seller_brand_authorizations WHERE seller_id = NEW.id LOOP
      PERFORM revalidate_brand(r.brand_id);
    END LOOP;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."trg_seller_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_taxonomy_node_after"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.path IS DISTINCT FROM OLD.path THEN
    -- a live page now owns this path: drop any redirect that would shadow it
    DELETE FROM route_redirects WHERE tenant_id = NEW.tenant_id AND from_path = NEW.path;
    IF pg_trigger_depth() = 1 THEN
      -- one prefix redirect covers the node, all descendants and the brand pages under them
      INSERT INTO route_redirects (tenant_id, from_path, to_path, match_type, reason)
      VALUES (NEW.tenant_id, OLD.path, NEW.path, 'prefix', 'category renamed or moved')
      ON CONFLICT (tenant_id, from_path) DO UPDATE
        SET to_path = EXCLUDED.to_path, match_type = 'prefix', created_at = now();
      -- collapse chains (A->B, B->C  =>  A->C)
      UPDATE route_redirects
         SET to_path = NEW.path || substr(to_path, length(OLD.path) + 1)
       WHERE tenant_id = NEW.tenant_id AND from_path <> OLD.path
         AND (to_path = OLD.path OR to_path LIKE OLD.path || '/%');
    END IF;
    -- cascade: children recompute their path from this node
    UPDATE taxonomy_nodes SET updated_at = now() WHERE parent_id = NEW.id;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."trg_taxonomy_node_after"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_taxonomy_node_before"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE p taxonomy_nodes%ROWTYPE; base TEXT; n INT := 1;
BEGIN
  IF NEW.slug IS NULL OR NEW.slug = '' THEN NEW.slug := slugify(NEW.name); END IF;

  IF NEW.parent_id IS NULL THEN
    IF NEW.node_type <> 'animal' THEN
      RAISE EXCEPTION 'Only animal nodes can be top level (got % "%")', NEW.node_type, NEW.name;
    END IF;
    NEW.depth := 1;
    NEW.animal_id := NEW.id;
  ELSE
    SELECT * INTO p FROM taxonomy_nodes WHERE id = NEW.parent_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Parent node % not found', NEW.parent_id; END IF;
    IF p.tenant_id <> NEW.tenant_id THEN RAISE EXCEPTION 'Parent node belongs to another tenant'; END IF;
    IF NEW.node_type = 'animal' THEN RAISE EXCEPTION 'Animal nodes must be top level'; END IF;
    IF TG_OP = 'UPDATE' AND (p.id = NEW.id OR p.path LIKE OLD.path || '/%') THEN
      RAISE EXCEPTION 'Cannot move "%" under its own descendant', NEW.name;
    END IF;
    NEW.depth := p.depth + 1;
    NEW.animal_id := p.animal_id;
  END IF;

  IF TG_OP = 'INSERT' OR NEW.slug IS DISTINCT FROM OLD.slug OR NEW.parent_id IS DISTINCT FROM OLD.parent_id THEN
    base := NEW.slug;
    WHILE EXISTS (SELECT 1 FROM taxonomy_nodes t
                   WHERE t.tenant_id = NEW.tenant_id AND t.parent_id IS NOT DISTINCT FROM NEW.parent_id
                     AND t.slug = NEW.slug AND t.id <> NEW.id) LOOP
      n := n + 1;
      NEW.slug := base || '-' || n;
    END LOOP;
  END IF;

  NEW.path := CASE WHEN NEW.parent_id IS NULL THEN '/shop/' || NEW.slug ELSE p.path || '/' || NEW.slug END;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."trg_taxonomy_node_before"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_portal_account_link"("p_provider" "text", "p_sub" "text", "p_email" "text", "p_type" "text", "p_entity" "uuid", "p_tenant" "uuid" DEFAULT NULL::"uuid", "p_picture" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
    v_link_id UUID;
BEGIN
    IF p_provider IS NULL OR p_sub IS NULL OR p_email IS NULL OR p_type IS NULL OR p_entity IS NULL THEN
        RAISE EXCEPTION 'upsert_portal_account_link: provider, sub, email, type, entity_id are all required';
    END IF;
    IF p_type NOT IN ('staff', 'customer', 'tenant_membership') THEN
        RAISE EXCEPTION 'upsert_portal_account_link: invalid entity_type %', p_type;
    END IF;

    INSERT INTO public.portal_account_links (
        provider, provider_sub, email, entity_type, entity_id, tenant_id, picture_url, display_name
    ) VALUES (
        p_provider, p_sub, LOWER(p_email), p_type, p_entity, p_tenant, p_picture, p_name
    )
    ON CONFLICT (provider, provider_sub)
    DO UPDATE SET
        email        = EXCLUDED.email,
        entity_type  = EXCLUDED.entity_type,
        entity_id    = EXCLUDED.entity_id,
        tenant_id    = COALESCE(EXCLUDED.tenant_id, portal_account_links.tenant_id),
        picture_url  = COALESCE(EXCLUDED.picture_url, portal_account_links.picture_url),
        display_name = COALESCE(EXCLUDED.display_name, portal_account_links.display_name),
        last_used_at = NOW()
    RETURNING id INTO v_link_id;

    RETURN v_link_id;
END;
$$;


ALTER FUNCTION "public"."upsert_portal_account_link"("p_provider" "text", "p_sub" "text", "p_email" "text", "p_type" "text", "p_entity" "uuid", "p_tenant" "uuid", "p_picture" "text", "p_name" "text") OWNER TO "postgres";


