CREATE OR REPLACE VIEW "lms"."v_ai_usage_summary" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "date_trunc"('day'::"text", "created_at") AS "usage_date",
    "model_name",
    "usage_type",
    "sum"("input_tokens") AS "total_input_tokens",
    "sum"("output_tokens") AS "total_output_tokens",
    "sum"("total_tokens") AS "total_tokens",
    "sum"("estimated_cost") AS "total_cost",
    "count"(*) AS "request_count"
   FROM "lms"."ai_usage_tracking"
  GROUP BY "tenant_id", ("date_trunc"('day'::"text", "created_at")), "model_name", "usage_type"
  ORDER BY ("date_trunc"('day'::"text", "created_at")) DESC;


ALTER VIEW "lms"."v_ai_usage_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_clock_hour_audit_summary" WITH ("security_invoker"='on') AS
 SELECT "chl"."tenant_id",
    "chl"."learner_user_id",
    "chl"."enrollment_id",
    "c"."title" AS "course_title",
    "sum"(
        CASE
            WHEN ("chl"."voided_at" IS NULL) THEN ("chl"."computed_minutes" / 60.0)
            ELSE (0)::numeric
        END) AS "total_computed_hours",
    "sum"(
        CASE
            WHEN (("chl"."voided_at" IS NULL) AND ("chl"."verification_status" = 'human_verified'::"text")) THEN ("chl"."verified_minutes" / 60.0)
            ELSE (0)::numeric
        END) AS "total_verified_hours",
    "sum"(
        CASE
            WHEN (("chl"."voided_at" IS NULL) AND ("chl"."verification_status" = 'computed'::"text")) THEN 1
            ELSE 0
        END) AS "pending_verification_count",
    "sum"(
        CASE
            WHEN ("chl"."voided_at" IS NOT NULL) THEN 1
            ELSE 0
        END) AS "voided_entries_count",
    "count"(*) AS "total_entries"
   FROM (("lms"."clock_hour_ledger" "chl"
     JOIN "lms"."enrollments" "e" ON ((("e"."tenant_id" = "chl"."tenant_id") AND ("e"."id" = "chl"."enrollment_id"))))
     JOIN "lms"."courses" "c" ON ((("c"."tenant_id" = "chl"."tenant_id") AND ("c"."id" = "e"."course_id"))))
  GROUP BY "chl"."tenant_id", "chl"."learner_user_id", "chl"."enrollment_id", "c"."title";


ALTER VIEW "lms"."v_clock_hour_audit_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_cohort_health" WITH ("security_invoker"='on') AS
 SELECT "co"."tenant_id",
    "co"."id" AS "cohort_id",
    "co"."name" AS "cohort_name",
    "co"."course_id",
    "c"."title" AS "course_title",
    "co"."start_date",
    "co"."end_date",
    "count"("e"."id") AS "total_enrollments",
    "count"("e"."id") FILTER (WHERE ("e"."status" = 'active'::"text")) AS "active_enrollments",
    "count"("e"."id") FILTER (WHERE ("e"."status" = 'completed'::"text")) AS "completed_enrollments",
    "count"("arl"."id") FILTER (WHERE ("arl"."risk_level" = ANY (ARRAY['high'::"text", 'critical'::"text"]))) AS "at_risk_count",
    "round"("avg"("e"."progress_percentage"), 2) AS "avg_progress"
   FROM ((("lms"."cohorts" "co"
     JOIN "lms"."courses" "c" ON ((("c"."tenant_id" = "co"."tenant_id") AND ("c"."id" = "co"."course_id"))))
     LEFT JOIN "lms"."enrollments" "e" ON ((("e"."tenant_id" = "co"."tenant_id") AND ("e"."cohort_id" = "co"."id"))))
     LEFT JOIN "lms"."at_risk_learners" "arl" ON ((("arl"."tenant_id" = "e"."tenant_id") AND ("arl"."enrollment_id" = "e"."id"))))
  GROUP BY "co"."tenant_id", "co"."id", "co"."name", "co"."course_id", "c"."title", "co"."start_date", "co"."end_date";


ALTER VIEW "lms"."v_cohort_health" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_course_completion_summary" WITH ("security_invoker"='on') AS
 SELECT "e"."tenant_id",
    "e"."course_id",
    "c"."title" AS "course_title",
    "count"(*) AS "total_enrollments",
    "count"(*) FILTER (WHERE ("e"."status" = 'completed'::"text")) AS "completed_count",
    "count"(*) FILTER (WHERE ("e"."status" = 'active'::"text")) AS "active_count",
    "count"(*) FILTER (WHERE ("e"."status" = 'dropped'::"text")) AS "dropped_count",
    "round"("avg"("e"."progress_percentage"), 2) AS "avg_progress",
    "round"(((("count"(*) FILTER (WHERE ("e"."status" = 'completed'::"text")))::numeric / (NULLIF("count"(*), 0))::numeric) * (100)::numeric), 2) AS "completion_rate"
   FROM ("lms"."enrollments" "e"
     JOIN "lms"."courses" "c" ON ((("c"."tenant_id" = "e"."tenant_id") AND ("c"."id" = "e"."course_id"))))
  GROUP BY "e"."tenant_id", "e"."course_id", "c"."title";


ALTER VIEW "lms"."v_course_completion_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_learner_clock_hours" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "learner_user_id",
    "enrollment_id",
    "course_id",
    "hour_category",
    "round"(("sum"("computed_minutes") / 60.0), 2) AS "computed_hours",
    "round"(("sum"("verified_minutes") / 60.0), 2) AS "verified_hours",
    "count"(*) AS "entry_count",
    "count"(*) FILTER (WHERE ("verification_status" = 'human_verified'::"text")) AS "verified_entries",
    "count"(*) FILTER (WHERE ("verification_status" = ANY (ARRAY['computed'::"text", 'ai_verified_pending_human'::"text"]))) AS "pending_entries",
    "count"(*) FILTER (WHERE ("verification_status" = 'disputed'::"text")) AS "disputed_entries"
   FROM "lms"."clock_hour_ledger" "l"
  WHERE ("voided_at" IS NULL)
  GROUP BY "tenant_id", "learner_user_id", "enrollment_id", "course_id", "hour_category";


ALTER VIEW "lms"."v_learner_clock_hours" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_skill_progress_authority" WITH ("security_invoker"='on') AS
 SELECT "sp"."tenant_id",
    "sp"."learner_user_id",
    "sp"."skill_id",
    "s"."name" AS "skill_name",
    "s"."skill_domain_id",
    "sp"."enrollment_id",
    "sp"."competency_level",
    "sp"."signed_off_level",
    "sp"."signoff_source",
    "lms"."competency_rank"(COALESCE("sp"."signed_off_level", 'not_started'::"text")) AS "effective_rank",
        CASE "lms"."competency_rank"(COALESCE("sp"."signed_off_level", 'not_started'::"text"))
            WHEN 3 THEN 'mastered'::"text"
            WHEN 2 THEN 'practiced'::"text"
            WHEN 1 THEN 'introduced'::"text"
            ELSE 'not_started'::"text"
        END AS "effective_level",
    (COALESCE("sp"."signed_off_level", 'not_started'::"text") = 'mastered'::"text") AS "is_mastered",
    GREATEST("lms"."competency_rank"("sp"."competency_level"), "lms"."competency_rank"(COALESCE("sp"."signed_off_level", 'not_started'::"text"))) AS "coursework_rank",
    (("sp"."competency_level" = 'mastered'::"text") AND (COALESCE("sp"."signed_off_level", 'not_started'::"text") <> 'mastered'::"text")) AS "unbacked_mastery_claim",
    "sp"."progress_percentage",
    "sp"."assessment_count",
    "sp"."practice_count",
    "sp"."last_assessed_at",
    "sp"."last_assessment_score",
    "sp"."signed_off_at",
    "sp"."signed_off_by",
    "sp"."last_recomputed_at",
    ("sp"."last_recomputed_at" IS NULL) AS "never_recomputed"
   FROM ("lms"."skill_progress" "sp"
     JOIN "lms"."skills" "s" ON ((("s"."tenant_id" = "sp"."tenant_id") AND ("s"."id" = "sp"."skill_id"))));


ALTER VIEW "lms"."v_skill_progress_authority" OWNER TO "postgres";


COMMENT ON VIEW "lms"."v_skill_progress_authority" IS 'THE authoritative read of skill mastery. Every credential gate, report and TypeScript query must read effective_level / is_mastered from here rather than joining skill_signoffs or skill_signoff_events directly.';



CREATE OR REPLACE VIEW "lms"."v_credential_readiness" WITH ("security_invoker"='on') AS
 SELECT "cd"."tenant_id",
    "cd"."id" AS "credential_definition_id",
    "cd"."code" AS "credential_code",
    "cd"."title" AS "credential_title",
    "e"."learner_user_id",
    "e"."id" AS "enrollment_id",
    "count"("cds"."skill_id") AS "skills_required",
    "count"(*) FILTER (WHERE ("spa"."effective_rank" >= "lms"."competency_rank"("cds"."required_level"))) AS "skills_met",
    "bool_and"((COALESCE("spa"."effective_rank", 0) >= "lms"."competency_rank"("cds"."required_level"))) AS "all_skills_met",
    COALESCE("hrs"."verified_hours", (0)::numeric) AS "verified_hours",
    "cd"."required_clock_hours",
    (("cd"."required_clock_hours" IS NULL) OR (COALESCE("hrs"."verified_hours", (0)::numeric) >= "cd"."required_clock_hours")) AS "hours_met"
   FROM (((("lms"."credential_definitions" "cd"
     JOIN "lms"."enrollments" "e" ON ((("e"."tenant_id" = "cd"."tenant_id") AND (("cd"."course_id" IS NULL) OR ("e"."course_id" = "cd"."course_id")))))
     LEFT JOIN "lms"."credential_definition_skills" "cds" ON ((("cds"."tenant_id" = "cd"."tenant_id") AND ("cds"."credential_definition_id" = "cd"."id"))))
     LEFT JOIN "lms"."v_skill_progress_authority" "spa" ON ((("spa"."tenant_id" = "cd"."tenant_id") AND ("spa"."learner_user_id" = "e"."learner_user_id") AND ("spa"."skill_id" = "cds"."skill_id"))))
     LEFT JOIN LATERAL ( SELECT "sum"("v"."verified_hours") AS "verified_hours"
           FROM "lms"."v_learner_clock_hours" "v"
          WHERE (("v"."tenant_id" = "cd"."tenant_id") AND ("v"."learner_user_id" = "e"."learner_user_id") AND (("cd"."course_id" IS NULL) OR ("v"."course_id" = "cd"."course_id")))) "hrs" ON (true))
  WHERE "cd"."is_active"
  GROUP BY "cd"."tenant_id", "cd"."id", "cd"."code", "cd"."title", "e"."learner_user_id", "e"."id", "cd"."required_clock_hours", "hrs"."verified_hours";


ALTER VIEW "lms"."v_credential_readiness" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_instructor_workload" WITH ("security_invoker"='on') AS
 SELECT "ci"."tenant_id",
    "ci"."instructor_user_id",
    "count"(DISTINCT "ci"."course_id") AS "course_count",
    "count"(DISTINCT "e"."id") AS "total_enrollments",
    "count"(DISTINCT "e"."id") FILTER (WHERE ("e"."status" = 'active'::"text")) AS "active_enrollments",
    "count"(DISTINCT "sa"."id") AS "pending_submissions",
    "count"(DISTINCT "qa"."id") AS "pending_quiz_grading"
   FROM ((("lms"."course_instructors" "ci"
     LEFT JOIN "lms"."enrollments" "e" ON ((("e"."tenant_id" = "ci"."tenant_id") AND ("e"."course_id" = "ci"."course_id"))))
     LEFT JOIN "lms"."artifact_submissions" "sa" ON ((("sa"."tenant_id" = "ci"."tenant_id") AND ("sa"."enrollment_id" = "e"."id") AND ("sa"."status" = 'submitted'::"text"))))
     LEFT JOIN "lms"."quiz_attempts" "qa" ON ((("qa"."tenant_id" = "ci"."tenant_id") AND ("qa"."enrollment_id" = "e"."id") AND ("qa"."status" = 'submitted'::"text"))))
  WHERE ("ci"."is_active" = true)
  GROUP BY "ci"."tenant_id", "ci"."instructor_user_id";


ALTER VIEW "lms"."v_instructor_workload" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_learner_dashboard" WITH ("security_invoker"='on') AS
 SELECT "e"."tenant_id",
    "e"."learner_user_id",
    "e"."id" AS "enrollment_id",
    "e"."course_id",
    "c"."title" AS "course_title",
    "e"."status" AS "enrollment_status",
    "e"."enrolled_at",
    "e"."delivery_mode",
    "e"."progress_percentage",
    COALESCE("chl"."total_hours", (0)::numeric) AS "total_clock_hours",
    COALESCE("chl"."verified_hours", (0)::numeric) AS "verified_clock_hours",
    COALESCE("chl"."pending_count", (0)::bigint) AS "pending_verification_count",
    COALESCE("arl"."risk_level", 'low'::"text") AS "risk_level",
    "e"."completed_at"
   FROM ((("lms"."enrollments" "e"
     JOIN "lms"."courses" "c" ON ((("c"."tenant_id" = "e"."tenant_id") AND ("c"."id" = "e"."course_id"))))
     LEFT JOIN ( SELECT "clock_hour_ledger"."tenant_id",
            "clock_hour_ledger"."enrollment_id",
            "sum"(
                CASE
                    WHEN ("clock_hour_ledger"."voided_at" IS NULL) THEN ("clock_hour_ledger"."computed_minutes" / 60.0)
                    ELSE (0)::numeric
                END) AS "total_hours",
            "sum"(
                CASE
                    WHEN (("clock_hour_ledger"."voided_at" IS NULL) AND ("clock_hour_ledger"."verification_status" = 'human_verified'::"text")) THEN ("clock_hour_ledger"."verified_minutes" / 60.0)
                    ELSE (0)::numeric
                END) AS "verified_hours",
            "sum"(
                CASE
                    WHEN (("clock_hour_ledger"."voided_at" IS NULL) AND ("clock_hour_ledger"."verification_status" = 'computed'::"text")) THEN 1
                    ELSE 0
                END) AS "pending_count"
           FROM "lms"."clock_hour_ledger"
          GROUP BY "clock_hour_ledger"."tenant_id", "clock_hour_ledger"."enrollment_id") "chl" ON ((("chl"."tenant_id" = "e"."tenant_id") AND ("chl"."enrollment_id" = "e"."id"))))
     LEFT JOIN "lms"."at_risk_learners" "arl" ON ((("arl"."tenant_id" = "e"."tenant_id") AND ("arl"."enrollment_id" = "e"."id"))))
  WHERE ("e"."status" = ANY (ARRAY['active'::"text", 'completed'::"text"]));


ALTER VIEW "lms"."v_learner_dashboard" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "lms"."workforce_outcomes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "learner_user_id" "uuid" NOT NULL,
    "course_id" "uuid",
    "credential_id" "uuid",
    "outcome_type" "text" NOT NULL,
    "employer_name" "text",
    "job_title" "text",
    "hourly_wage" numeric(10,2),
    "previous_hourly_wage" numeric(10,2),
    "wage_change_percent" numeric(6,2),
    "employment_start_date" "date",
    "outcome_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "verification_method" "text",
    "verified_by" "uuid",
    "verified_at" timestamp with time zone,
    "notes" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workforce_outcomes_outcome_type_check" CHECK (("outcome_type" = ANY (ARRAY['employment'::"text", 'wage_increase'::"text", 'promotion'::"text", 'business_launch'::"text", 'retention_90_day'::"text", 'retention_180_day'::"text", 'retention_365_day'::"text", 'continued_education'::"text", 'licensure_obtained'::"text"]))),
    CONSTRAINT "workforce_outcomes_verification_method_check" CHECK (("verification_method" = ANY (ARRAY['self_reported'::"text", 'employer_verified'::"text", 'pay_stub_verified'::"text", 'navigator_verified'::"text"])))
);


ALTER TABLE "lms"."workforce_outcomes" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_navigator_caseload_summary" WITH ("security_invoker"='on') AS
 SELECT "nc"."tenant_id",
    "nc"."navigator_user_id",
    "count"(DISTINCT "nc"."learner_user_id") AS "total_caseload",
    "count"(DISTINCT "nc"."learner_user_id") FILTER (WHERE ("nc"."status" = 'active'::"text")) AS "active_caseload",
    "count"(DISTINCT "sr"."id") FILTER (WHERE ("sr"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"]))) AS "open_referrals",
    "count"(DISTINCT "si"."id") FILTER (WHERE ("si"."status" = ANY (ARRAY['open'::"text", 'under_review'::"text"]))) AS "open_safety_incidents",
    "count"(DISTINCT "wo"."id") FILTER (WHERE ("wo"."outcome_type" = 'employment'::"text")) AS "employment_outcomes"
   FROM ((("lms"."navigator_caseloads" "nc"
     LEFT JOIN "lms"."support_referrals" "sr" ON ((("sr"."tenant_id" = "nc"."tenant_id") AND ("sr"."learner_user_id" = "nc"."learner_user_id"))))
     LEFT JOIN "lms"."safety_incidents" "si" ON ((("si"."tenant_id" = "nc"."tenant_id") AND ("si"."learner_user_id" = "nc"."learner_user_id"))))
     LEFT JOIN "lms"."workforce_outcomes" "wo" ON ((("wo"."tenant_id" = "nc"."tenant_id") AND ("wo"."learner_user_id" = "nc"."learner_user_id"))))
  GROUP BY "nc"."tenant_id", "nc"."navigator_user_id";


ALTER VIEW "lms"."v_navigator_caseload_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_pending_ai_approvals" WITH ("security_invoker"='on') AS
 SELECT 'lecture'::"text" AS "entity_type",
    "ai_generated_lectures"."tenant_id",
    "ai_generated_lectures"."id" AS "entity_id",
    "ai_generated_lectures"."created_at"
   FROM "lms"."ai_generated_lectures"
  WHERE ("ai_generated_lectures"."approval_status" = 'pending_review'::"text")
UNION ALL
 SELECT 'content_draft'::"text" AS "entity_type",
    "ai_content_drafts"."tenant_id",
    "ai_content_drafts"."id" AS "entity_id",
    "ai_content_drafts"."created_at"
   FROM "lms"."ai_content_drafts"
  WHERE ("ai_content_drafts"."status" = 'pending_review'::"text")
UNION ALL
 SELECT 'assessment_job'::"text" AS "entity_type",
    "ai_assessment_generation_jobs"."tenant_id",
    "ai_assessment_generation_jobs"."id" AS "entity_id",
    "ai_assessment_generation_jobs"."created_at"
   FROM "lms"."ai_assessment_generation_jobs"
  WHERE ("ai_assessment_generation_jobs"."status" = 'completed'::"text")
UNION ALL
 SELECT 'question'::"text" AS "entity_type",
    "question_bank"."tenant_id",
    "question_bank"."id" AS "entity_id",
    "question_bank"."created_at"
   FROM "lms"."question_bank"
  WHERE (("question_bank"."is_ai_generated" = true) AND ("question_bank"."is_ai_approved" = false))
UNION ALL
 SELECT 'quiz'::"text" AS "entity_type",
    "quizzes"."tenant_id",
    "quizzes"."id" AS "entity_id",
    "quizzes"."created_at"
   FROM "lms"."quizzes"
  WHERE (("quizzes"."is_ai_generated" = true) AND ("quizzes"."is_ai_approved" = false))
UNION ALL
 SELECT 'assignment'::"text" AS "entity_type",
    "assignments"."tenant_id",
    "assignments"."id" AS "entity_id",
