   FROM "lms"."assignments"
  WHERE (("assignments"."is_ai_drafted" = true) AND ("assignments"."is_ai_approved" = false))
  ORDER BY 4 DESC;


ALTER VIEW "lms"."v_pending_ai_approvals" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_skill_mastery_summary" WITH ("security_invoker"='on') AS
 SELECT "sp"."tenant_id",
    "sp"."learner_user_id",
    "sp"."skill_id",
    "s"."name" AS "skill_name",
    "s"."skill_domain_id",
    "sd"."name" AS "domain_name",
    "sp"."enrollment_id",
    "sp"."competency_level",
    "sp"."progress_percentage",
    "sp"."is_signed_off",
    "sp"."signed_off_at",
    "sp"."signed_off_by",
    "sp"."last_assessed_at",
    "sp"."last_assessment_score",
    "sp"."assessment_count",
    "sp"."practice_count",
    "so"."signoff_level" AS "latest_signoff_level",
    "so"."signoff_method" AS "latest_signoff_method",
    "so"."verified_by" AS "latest_signoff_verified_by",
    "so"."verified_at" AS "latest_signoff_at",
    "se"."signoff_level" AS "latest_event_level",
    "se"."status" AS "latest_event_status",
    "se"."signoff_user_id" AS "latest_event_user",
    "se"."created_at" AS "latest_event_at"
   FROM (((("lms"."skill_progress" "sp"
     LEFT JOIN "lms"."skills" "s" ON ((("s"."id" = "sp"."skill_id") AND ("s"."tenant_id" = "sp"."tenant_id"))))
     LEFT JOIN "lms"."skill_domains" "sd" ON ((("sd"."id" = "s"."skill_domain_id") AND ("sd"."tenant_id" = "sp"."tenant_id"))))
     LEFT JOIN LATERAL ( SELECT "skill_signoffs"."id",
            "skill_signoffs"."tenant_id",
            "skill_signoffs"."learner_user_id",
            "skill_signoffs"."skill_id",
            "skill_signoffs"."course_id",
            "skill_signoffs"."assessment_id",
            "skill_signoffs"."signoff_level",
            "skill_signoffs"."signoff_method",
            "skill_signoffs"."verified_by",
            "skill_signoffs"."verified_at",
            "skill_signoffs"."evidence_url",
            "skill_signoffs"."notes",
            "skill_signoffs"."metadata",
            "skill_signoffs"."created_at"
           FROM "lms"."skill_signoffs"
          WHERE (("skill_signoffs"."tenant_id" = "sp"."tenant_id") AND ("skill_signoffs"."learner_user_id" = "sp"."learner_user_id") AND ("skill_signoffs"."skill_id" = "sp"."skill_id"))
          ORDER BY "skill_signoffs"."verified_at" DESC
         LIMIT 1) "so" ON (true))
     LEFT JOIN LATERAL ( SELECT "skill_signoff_events"."id",
            "skill_signoff_events"."tenant_id",
            "skill_signoff_events"."skill_id",
            "skill_signoff_events"."learner_user_id",
            "skill_signoff_events"."signoff_user_id",
            "skill_signoff_events"."signoff_level",
            "skill_signoff_events"."evidence_url",
            "skill_signoff_events"."notes",
            "skill_signoff_events"."status",
            "skill_signoff_events"."created_at",
            "skill_signoff_events"."updated_at"
           FROM "lms"."skill_signoff_events"
          WHERE (("skill_signoff_events"."tenant_id" = "sp"."tenant_id") AND ("skill_signoff_events"."learner_user_id" = "sp"."learner_user_id") AND ("skill_signoff_events"."skill_id" = "sp"."skill_id"))
          ORDER BY "skill_signoff_events"."created_at" DESC
         LIMIT 1) "se" ON (true));


ALTER VIEW "lms"."v_skill_mastery_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "lms"."v_skill_progress_drift" WITH ("security_invoker"='on') AS
 WITH "latest_approved" AS (
         SELECT "s"."tenant_id",
            "s"."learner_user_id",
            "s"."skill_id",
            "max"("s"."verified_at") AS "approved_at"
           FROM "lms"."skill_signoffs" "s"
          WHERE (("s"."status" = 'approved'::"text") AND ("s"."automatic_fail" = false))
          GROUP BY "s"."tenant_id", "s"."learner_user_id", "s"."skill_id"
        ), "blocked" AS (
         SELECT DISTINCT "s"."tenant_id",
            "s"."learner_user_id",
            "s"."skill_id"
           FROM ("lms"."skill_signoffs" "s"
             LEFT JOIN "latest_approved" "la" ON ((("la"."tenant_id" = "s"."tenant_id") AND ("la"."learner_user_id" = "s"."learner_user_id") AND ("la"."skill_id" = "s"."skill_id"))))
          WHERE ((("s"."automatic_fail" = true) OR ("s"."status" = 'revoked'::"text")) AND ("s"."verified_at" >= COALESCE("la"."approved_at", '-infinity'::timestamp with time zone)))
        )
 SELECT "sp"."tenant_id",
    "sp"."learner_user_id",
    "sp"."skill_id",
    "sp"."competency_level",
    "sp"."signed_off_level",
    "so"."best_signoff_level",
    "ev"."best_event_level",
    ("bl"."skill_id" IS NOT NULL) AS "is_blocked",
        CASE
            WHEN ("bl"."skill_id" IS NOT NULL) THEN NULL::"text"
            WHEN (("so"."best_signoff_level" IS NOT NULL) AND (("ev"."best_event_level" IS NULL) OR ("lms"."competency_rank"("so"."best_signoff_level") >= "lms"."competency_rank"("ev"."best_event_level")))) THEN "so"."best_signoff_level"
            ELSE "ev"."best_event_level"
        END AS "expected_signed_off_level",
    "sp"."last_recomputed_at"
   FROM ((("lms"."skill_progress" "sp"
     LEFT JOIN LATERAL ( SELECT "s"."signoff_level" AS "best_signoff_level"
           FROM "lms"."skill_signoffs" "s"
          WHERE (("s"."tenant_id" = "sp"."tenant_id") AND ("s"."learner_user_id" = "sp"."learner_user_id") AND ("s"."skill_id" = "sp"."skill_id") AND ("s"."status" = 'approved'::"text") AND ("s"."automatic_fail" = false))
          ORDER BY ("lms"."competency_rank"("s"."signoff_level")) DESC, "s"."verified_at" DESC
         LIMIT 1) "so" ON (true))
     LEFT JOIN LATERAL ( SELECT "e"."signoff_level" AS "best_event_level"
           FROM "lms"."skill_signoff_events" "e"
          WHERE (("e"."tenant_id" = "sp"."tenant_id") AND ("e"."learner_user_id" = "sp"."learner_user_id") AND ("e"."skill_id" = "sp"."skill_id") AND ("e"."status" = 'approved'::"text"))
          ORDER BY ("lms"."competency_rank"("e"."signoff_level")) DESC, "e"."created_at" DESC
         LIMIT 1) "ev" ON (true))
     LEFT JOIN "blocked" "bl" ON ((("bl"."tenant_id" = "sp"."tenant_id") AND ("bl"."learner_user_id" = "sp"."learner_user_id") AND ("bl"."skill_id" = "sp"."skill_id"))))
  WHERE ("sp"."signed_off_level" IS DISTINCT FROM
        CASE
            WHEN ("bl"."skill_id" IS NOT NULL) THEN NULL::"text"
            WHEN (("so"."best_signoff_level" IS NOT NULL) AND (("ev"."best_event_level" IS NULL) OR ("lms"."competency_rank"("so"."best_signoff_level") >= "lms"."competency_rank"("ev"."best_event_level")))) THEN "so"."best_signoff_level"
            ELSE "ev"."best_event_level"
        END);


ALTER VIEW "lms"."v_skill_progress_drift" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "lms"."webhook_log" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
