    "response_status" integer,
    "response_body" "text",
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "webhook_log_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'sent'::"text", 'delivered'::"text", 'failed'::"text", 'retried'::"text"]))),
    CONSTRAINT "webhook_log_webhook_type_check" CHECK (("webhook_type" = ANY (ARRAY['outbound'::"text", 'inbound'::"text"])))
);


ALTER TABLE "lms"."webhook_log" OWNER TO "postgres";


