    "expected_result" "text",
    "owner" "text",
    "is_release_blocking" boolean DEFAULT true NOT NULL,
    CONSTRAINT "control_catalog_severity_check" CHECK (("severity" = ANY (ARRAY['blocker'::"text", 'high'::"text", 'medium'::"text", 'low'::"text", 'info'::"text"])))
);


ALTER TABLE "platform_audit"."control_catalog" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "platform_audit"."control_results" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_id" "uuid" NOT NULL,
    "control_id" "text" NOT NULL,
