CREATE OR REPLACE VIEW "public"."account_balances" WITH ("security_invoker"='on') AS
 SELECT "a"."tenant_id",
    "a"."id" AS "account_id",
    "a"."code",
    "a"."name",
    "a"."type",
    "a"."subtype",
    COALESCE("sum"("l"."debit"), (0)::numeric) AS "total_debit",
    COALESCE("sum"("l"."credit"), (0)::numeric) AS "total_credit",
    (COALESCE("sum"("l"."debit"), (0)::numeric) - COALESCE("sum"("l"."credit"), (0)::numeric)) AS "balance"
   FROM ("public"."chart_of_accounts" "a"
     LEFT JOIN "public"."journal_lines" "l" ON (("l"."account_id" = "a"."id")))
  GROUP BY "a"."tenant_id", "a"."id", "a"."code", "a"."name", "a"."type", "a"."subtype";


