CREATE OR REPLACE VIEW "public"."acct_ap_aging" WITH ("security_invoker"='on') AS
 SELECT "b"."tenant_id",
    "b"."entity_id",
    "b"."id" AS "bill_id",
    "b"."bill_number",
    "b"."vendor_id",
    "v"."legal_name" AS "vendor_name",
    "b"."bill_date",
    "b"."due_date",
    GREATEST((("b"."total" - "b"."amount_paid") - "b"."amount_credited"), (0)::numeric) AS "outstanding",
        CASE
            WHEN (CURRENT_DATE <= "b"."due_date") THEN 'current'::"text"
            WHEN (((CURRENT_DATE - "b"."due_date") >= 1) AND ((CURRENT_DATE - "b"."due_date") <= 30)) THEN '1-30'::"text"
            WHEN (((CURRENT_DATE - "b"."due_date") >= 31) AND ((CURRENT_DATE - "b"."due_date") <= 60)) THEN '31-60'::"text"
            WHEN (((CURRENT_DATE - "b"."due_date") >= 61) AND ((CURRENT_DATE - "b"."due_date") <= 90)) THEN '61-90'::"text"
            ELSE '90+'::"text"
        END AS "aging_bucket"
   FROM ("public"."acct_ap_bills" "b"
     JOIN "public"."acct_vendors" "v" ON (("v"."id" = "b"."vendor_id")))
  WHERE (("b"."status" <> ALL (ARRAY['void'::"public"."acct_document_status", 'cancelled'::"public"."acct_document_status"])) AND ((("b"."total" - "b"."amount_paid") - "b"."amount_credited") > (0)::numeric));


