CREATE OR REPLACE VIEW "public"."acct_trial_balance" WITH ("security_invoker"='on') AS
 SELECT "e"."tenant_id",
    "e"."id" AS "entity_id",
    "b"."id" AS "book_id",
    "p"."id" AS "period_id",
    "a"."id" AS "account_id",
    "a"."code",
    "a"."name",
    "a"."account_type",
    "a"."normal_balance",
    COALESCE("sum"("l"."debit"), (0)::numeric) AS "total_debits",
    COALESCE("sum"("l"."credit"), (0)::numeric) AS "total_credits",
    COALESCE("sum"(("l"."debit" - "l"."credit")), (0)::numeric) AS "signed_balance"
   FROM ((((("public"."acct_journal_lines" "l"
     JOIN "public"."acct_journal_entries" "j" ON ((("j"."id" = "l"."journal_entry_id") AND ("j"."status" = 'posted'::"public"."acct_posting_status"))))
     JOIN "public"."acct_entities" "e" ON (("e"."id" = "j"."entity_id")))
     JOIN "public"."acct_books" "b" ON (("b"."id" = "j"."book_id")))
     JOIN "public"."acct_periods" "p" ON (("p"."id" = "j"."period_id")))
     JOIN "public"."acct_chart_of_accounts" "a" ON (("a"."id" = "l"."account_id")))
  GROUP BY "e"."tenant_id", "e"."id", "b"."id", "p"."id", "a"."id", "a"."code", "a"."name", "a"."account_type", "a"."normal_balance";


ALTER VIEW "public"."acct_trial_balance" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."acct_balance_sheet" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "entity_id",
    "book_id",
    "period_id",
    "account_id",
    "code",
    "name",
    "account_type",
    "normal_balance",
    "total_debits",
    "total_credits",
    "signed_balance"
   FROM "public"."acct_trial_balance"
  WHERE ("account_type" = ANY (ARRAY['asset'::"public"."acct_account_type", 'liability'::"public"."acct_account_type", 'equity'::"public"."acct_account_type", 'contra_asset'::"public"."acct_account_type", 'contra_liability'::"public"."acct_account_type", 'contra_equity'::"public"."acct_account_type"]));


