CREATE OR REPLACE VIEW "public"."acct_cash_position" WITH ("security_invoker"='on') AS
 SELECT "ba"."tenant_id",
    "ba"."entity_id",
    "ba"."id" AS "bank_account_id",
    "ba"."name",
    "ba"."currency",
    COALESCE("sum"("bt"."amount"), (0)::numeric) AS "bank_activity"
   FROM ("public"."acct_bank_accounts" "ba"
     LEFT JOIN "public"."acct_bank_transactions" "bt" ON (("bt"."bank_account_id" = "ba"."id")))
  GROUP BY "ba"."tenant_id", "ba"."entity_id", "ba"."id", "ba"."name", "ba"."currency";


