CREATE OR REPLACE VIEW "public"."ar_aging" WITH ("security_invoker"='on') AS
 SELECT "i"."tenant_id",
    "i"."id" AS "invoice_id",
    "i"."number",
    "i"."customerId" AS "customer_id",
    (("c"."firstName" || ' '::"text") || "c"."lastName") AS "customer_name",
    ("i"."createdAt")::"date" AS "issue_date",
        CASE
            WHEN (("i"."createdAt")::"date" >= (CURRENT_DATE - '30 days'::interval)) THEN 'current'::"text"
            WHEN (("i"."createdAt")::"date" >= (CURRENT_DATE - '60 days'::interval)) THEN '1-30'::"text"
            WHEN (("i"."createdAt")::"date" >= (CURRENT_DATE - '90 days'::interval)) THEN '31-60'::"text"
            ELSE '90+'::"text"
        END AS "aging_bucket",
    ("i"."total")::numeric AS "total",
    COALESCE("i"."amount_paid", (0)::numeric) AS "amount_paid",
    (("i"."total")::numeric - COALESCE("i"."amount_paid", (0)::numeric)) AS "outstanding"
   FROM ("public"."invoices" "i"
     LEFT JOIN "public"."customers" "c" ON (("c"."id" = "i"."customerId")))
  WHERE (("i"."tenant_id" IS NOT NULL) AND (COALESCE("i"."status", ''::"text") = ANY (ARRAY['OPEN'::"text", 'PARTIAL'::"text", 'SENT'::"text", 'VIEWED'::"text", 'OVERDUE'::"text"])) AND (("i"."total")::numeric > COALESCE("i"."amount_paid", (0)::numeric)));


ALTER VIEW "public"."ar_aging" OWNER TO "postgres";


