    CONSTRAINT "crm_customers_customer_type_check" CHECK (("customer_type" = ANY (ARRAY['individual'::"text", 'business'::"text", 'breeder'::"text", 'rescue'::"text", 'referral_partner'::"text", 'staff'::"text", 'other'::"text"]))),
    CONSTRAINT "crm_customers_lifecycle_stage_check" CHECK (("lifecycle_stage" = ANY (ARRAY['new_lead'::"text", 'new_customer'::"text", 'active'::"text", 'vip'::"text", 'returning'::"text", 'lapsed'::"text", 'at_risk'::"text", 'lost'::"text"]))),
    CONSTRAINT "crm_customers_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['healthy'::"text", 'needs_attention'::"text", 'at_risk'::"text"]))),
    CONSTRAINT "crm_customers_no_show_rate_check" CHECK ((("no_show_rate" >= (0)::numeric) AND ("no_show_rate" <= (1)::numeric))),
    CONSTRAINT "crm_customers_preferred_contact_method_check" CHECK (("preferred_contact_method" = ANY (ARRAY['email'::"text", 'sms'::"text", 'phone'::"text", 'none'::"text"]))),
    CONSTRAINT "crm_customers_rebook_rate_check" CHECK ((("rebook_rate" >= (0)::numeric) AND ("rebook_rate" <= (1)::numeric))),
