CREATE OR REPLACE VIEW "public"."commerce_customer_360" WITH ("security_invoker"='on') AS
 SELECT "c"."id" AS "customer_id",
    "c"."tenant_id",
    "c"."first_name",
    "c"."last_name",
    "count"(DISTINCT "s"."id") AS "transaction_count",
    COALESCE("sum"("s"."total"), (0)::numeric) AS "lifetime_sales",
    COALESCE("sum"("s"."refunded_total"), (0)::numeric) AS "lifetime_refunds",
    "max"("s"."sale_at") AS "last_purchase_at",
    COALESCE("la"."points_balance", (0)::bigint) AS "loyalty_points",
    COALESCE("gc"."balance", (0)::numeric) AS "gift_card_balance",
    COALESCE("sc"."balance", (0)::numeric) AS "store_credit_balance",
    "count"(DISTINCT "sub"."id") FILTER (WHERE ("sub"."status" = 'active'::"text")) AS "active_subscriptions"
   FROM ((((("public"."crm_customers" "c"
     LEFT JOIN "public"."commerce_sales" "s" ON (("s"."customer_id" = "c"."id")))
     LEFT JOIN "public"."commerce_loyalty_accounts" "la" ON (("la"."customer_id" = "c"."id")))
     LEFT JOIN "public"."commerce_gift_cards" "gc" ON ((("gc"."customer_id" = "c"."id") AND ("gc"."status" = 'active'::"text"))))
     LEFT JOIN "public"."commerce_store_credits" "sc" ON ((("sc"."customer_id" = "c"."id") AND ("sc"."status" = 'active'::"text"))))
     LEFT JOIN "public"."commerce_subscriptions" "sub" ON (("sub"."customer_id" = "c"."id")))
  GROUP BY "c"."id", "c"."tenant_id", "c"."first_name", "c"."last_name", "la"."points_balance", "gc"."balance", "sc"."balance";


ALTER VIEW "public"."commerce_customer_360" OWNER TO "postgres";


