CREATE OR REPLACE VIEW "public"."commerce_sales_dashboard" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    ("date_trunc"('day'::"text", "sale_at"))::"date" AS "sale_date",
    "count"(*) AS "transaction_count",
    COALESCE("sum"("subtotal"), (0)::numeric) AS "subtotal",
    COALESCE("sum"("discount_total"), (0)::numeric) AS "discounts",
    COALESCE("sum"("tax_total"), (0)::numeric) AS "tax",
    COALESCE("sum"("total"), (0)::numeric) AS "gross_sales",
    COALESCE("sum"("refunded_total"), (0)::numeric) AS "refunds",
    COALESCE("sum"(("total" - "refunded_total")), (0)::numeric) AS "net_sales"
   FROM "public"."commerce_sales" "s"
  WHERE ("status" <> 'voided'::"text")
  GROUP BY "tenant_id", (("date_trunc"('day'::"text", "sale_at"))::"date");


ALTER VIEW "public"."commerce_sales_dashboard" OWNER TO "postgres";


