CREATE OR REPLACE VIEW "public"."crm_appointments_upcoming" WITH ("security_invoker"='on') AS
 SELECT "a"."id",
    "a"."tenant_id",
    "a"."source_appointment_id",
    "a"."customer_id",
    "a"."location_id",
    "a"."assigned_groomer_id",
    "a"."created_by",
    "a"."appointment_number",
    "a"."starts_at",
    "a"."ends_at",
    "a"."checked_in_at",
    "a"."started_at",
    "a"."completed_at",
    "a"."status",
    "a"."cancellation_reason",
    "a"."no_show_reason",
    "a"."service_type_confirmed",
    "a"."payment_method_confirmed",
    "a"."deposit_amount",
    "a"."subtotal",
    "a"."tax_total",
    "a"."total",
    "a"."amount_paid",
    "a"."outstanding_amount",
    "a"."currency",
    "a"."source_channel",
    "a"."booking_outcome",
    "a"."reminder_sent_at",
    "a"."pickup_notification_sent_at",
    "a"."processed_payment_sent_at",
    "a"."thank_you_sent_at",
    "a"."magic_link_sent_at",
    "a"."internal_notes",
    "a"."customer_notes",
    "a"."created_at",
    "a"."updated_at",
    "c"."first_name",
    "c"."last_name",
    "c"."preferred_name"
   FROM ("public"."crm_appointments" "a"
     JOIN "public"."crm_customers" "c" ON (("c"."id" = "a"."customer_id")))
  WHERE (("a"."starts_at" >= "now"()) AND ("a"."status" <> ALL (ARRAY['cancelled'::"text", 'no_show'::"text", 'completed'::"text"])));


ALTER VIEW "public"."crm_appointments_upcoming" OWNER TO "postgres";


