CREATE OR REPLACE VIEW "public"."crm_booking_funnel_30d" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "count"(*) FILTER (WHERE ("event_type" = 'website_visit'::"text")) AS "website_visits",
    "count"(*) FILTER (WHERE ("event_type" = 'account_created'::"text")) AS "accounts_created",
    "count"(*) FILTER (WHERE ("event_type" = 'intake_completed'::"text")) AS "intake_completed",
    "count"(*) FILTER (WHERE ("event_type" = 'booking_completed'::"text")) AS "bookings_completed"
   FROM "public"."crm_funnel_events" "f"
  WHERE ("occurred_at" >= ("now"() - '30 days'::interval))
  GROUP BY "tenant_id";


