CREATE OR REPLACE VIEW "public"."crm_customer_overview" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "count"(*) AS "total_customers",
    "count"(*) FILTER (WHERE "is_active") AS "active_customers",
    "count"(*) FILTER (WHERE ("customer_since" >= (CURRENT_DATE - '30 days'::interval))) AS "new_customers_30d",
    "count"(*) FILTER (WHERE (("lifecycle_status" = 'at_risk'::"text") OR ("lifecycle_stage" = 'at_risk'::"text"))) AS "at_risk_customers",
    "count"(*) FILTER (WHERE (("next_appointment_at" IS NOT NULL) AND ("next_appointment_at" >= "now"()))) AS "customers_with_upcoming_appointments",
    COALESCE("sum"("outstanding_balance"), (0)::numeric) AS "outstanding_balance",
    COALESCE("sum"("lifetime_value"), (0)::numeric) AS "lifetime_value"
   FROM "public"."crm_customers" "c"
  GROUP BY "tenant_id";


ALTER VIEW "public"."crm_customer_overview" OWNER TO "postgres";


