CREATE OR REPLACE VIEW "public"."crm_customer_service_profile" WITH ("security_invoker"='on') AS
 SELECT "c"."tenant_id",
    "c"."id" AS "customer_id",
    "mode"() WITHIN GROUP (ORDER BY "s"."id") AS "most_common_service_id",
    "avg"("asv"."duration_minutes") AS "average_service_duration",
    "avg"("asv"."unit_price") AS "average_service_spend",
    "max"("a"."starts_at") AS "last_service_at"
   FROM ((("public"."crm_customers" "c"
     LEFT JOIN "public"."crm_appointments" "a" ON ((("a"."customer_id" = "c"."id") AND ("a"."status" = 'completed'::"text"))))
     LEFT JOIN "public"."crm_appointment_services" "asv" ON (("asv"."appointment_id" = "a"."id")))
     LEFT JOIN "public"."crm_services" "s" ON (("s"."id" = "asv"."service_id")))
  GROUP BY "c"."tenant_id", "c"."id";


ALTER VIEW "public"."crm_customer_service_profile" OWNER TO "postgres";


