CREATE OR REPLACE VIEW "public"."crm_dashboard_daily" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    CURRENT_DATE AS "report_date",
    "count"(*) FILTER (WHERE (("starts_at" >= "date_trunc"('day'::"text", "now"())) AND ("starts_at" < ("date_trunc"('day'::"text", "now"()) + '1 day'::interval)))) AS "todays_appointments",
    COALESCE("sum"("total") FILTER (WHERE (("completed_at" >= "date_trunc"('day'::"text", "now"())) AND ("completed_at" < ("date_trunc"('day'::"text", "now"()) + '1 day'::interval)))), (0)::numeric) AS "todays_revenue",
    (("count"(*) FILTER (WHERE (("status" = 'no_show'::"text") AND ("starts_at" >= ("now"() - '30 days'::interval)))))::numeric / (NULLIF("count"(*) FILTER (WHERE (("starts_at" >= ("now"() - '30 days'::interval)) AND ("status" = ANY (ARRAY['completed'::"text", 'no_show'::"text"])))), 0))::numeric) AS "no_show_rate_30d",
    "count"(*) FILTER (WHERE (("status" = 'completed'::"text") AND ("starts_at" >= ("now"() - '30 days'::interval)))) AS "completed_appointments_30d"
   FROM "public"."crm_appointments" "a"
  GROUP BY "tenant_id";


ALTER VIEW "public"."crm_dashboard_daily" OWNER TO "postgres";


