CREATE OR REPLACE VIEW "public"."crm_needs_rebooking" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "id" AS "customer_id",
    "first_name",
    "last_name",
    "last_visit_at",
    "next_appointment_at",
    "average_visit_frequency_days",
    "rebook_rate",
    "lifecycle_stage"
   FROM "public"."crm_customers" "c"
  WHERE ("is_active" AND ("next_appointment_at" IS NULL) AND ("last_visit_at" IS NOT NULL) AND (CURRENT_DATE >= (("last_visit_at")::"date" + "make_interval"("days" => GREATEST((COALESCE("average_visit_frequency_days", (42)::numeric))::integer, 1)))));


