CREATE OR REPLACE VIEW "public"."crm_revenue_30d" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    COALESCE("sum"("total") FILTER (WHERE ("status" = 'completed'::"text")), (0)::numeric) AS "revenue_30d",
    "count"(*) FILTER (WHERE ("status" = 'completed'::"text")) AS "completed_visits_30d",
    "count"(*) FILTER (WHERE ("status" = 'no_show'::"text")) AS "no_shows_30d",
    "count"(*) FILTER (WHERE ("status" = 'cancelled'::"text")) AS "cancellations_30d"
   FROM "public"."crm_appointments"
  WHERE ("starts_at" >= ("now"() - '30 days'::interval))
  GROUP BY "tenant_id";


