CREATE OR REPLACE VIEW "public"."crm_unsigned_documents" WITH ("security_invoker"='on') AS
 SELECT "d"."tenant_id",
    "d"."id",
    "d"."customer_id",
    "d"."pet_id",
    "d"."name",
    "d"."status",
    "d"."expires_at",
    "dt"."name" AS "document_type"
   FROM ("public"."crm_documents" "d"
     LEFT JOIN "public"."crm_document_types" "dt" ON (("dt"."id" = "d"."document_type_id")))
  WHERE (("d"."status" = ANY (ARRAY['pending'::"text", 'submitted'::"text"])) OR ("dt"."requires_signature" AND ("d"."signed_at" IS NULL)));


ALTER VIEW "public"."crm_unsigned_documents" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."crm_upcoming_birthdays" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "id" AS "customer_id",
    "first_name",
    "last_name",
    "preferred_name",
    "date_of_birth"
   FROM "public"."crm_customers" "c"
  WHERE (("date_of_birth" IS NOT NULL) AND (EXTRACT(month FROM "date_of_birth") = EXTRACT(month FROM CURRENT_DATE)) AND "is_active");


ALTER VIEW "public"."crm_upcoming_birthdays" OWNER TO "postgres";


