CREATE OR REPLACE VIEW "public"."crm_vaccinations_expiring" WITH ("security_invoker"='on') AS
 SELECT "v"."tenant_id",
    "v"."id",
    "v"."pet_id",
    "p"."name" AS "pet_name",
    "p"."primary_customer_id" AS "customer_id",
    "v"."vaccine_type_id",
    "vt"."name" AS "vaccine_name",
    "v"."expires_on",
    ("v"."expires_on" - CURRENT_DATE) AS "days_until_expiry"
   FROM (("public"."crm_pet_vaccinations" "v"
     JOIN "public"."crm_pets" "p" ON (("p"."id" = "v"."pet_id")))
     JOIN "public"."crm_vaccine_types" "vt" ON (("vt"."id" = "v"."vaccine_type_id")))
  WHERE (("v"."expires_on" IS NOT NULL) AND ("v"."expires_on" <= (CURRENT_DATE + '30 days'::interval)) AND ("v"."status" = ANY (ARRAY['current'::"text", 'expiring'::"text"])));


ALTER VIEW "public"."crm_vaccinations_expiring" OWNER TO "postgres";


