    "allocated" numeric(18,4) DEFAULT 0 NOT NULL,
    "picked" numeric(18,4) DEFAULT 0 NOT NULL,
    "packed" numeric(18,4) DEFAULT 0 NOT NULL,
    "in_transit" numeric(18,4) DEFAULT 0 NOT NULL,
