    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "erp_inventory_balances_allocated_check" CHECK (("allocated" >= (0)::numeric)),
    CONSTRAINT "erp_inventory_balances_in_transit_check" CHECK (("in_transit" >= (0)::numeric)),
    CONSTRAINT "erp_inventory_balances_on_hand_check" CHECK (("on_hand" >= (0)::numeric)),
    CONSTRAINT "erp_inventory_balances_packed_check" CHECK (("packed" >= (0)::numeric)),
