CREATE OR REPLACE VIEW "public"."erp_inventory_availability" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "sku_id",
    "warehouse_id",
    "sum"("on_hand") AS "on_hand",
    "sum"("reserved") AS "reserved",
    "sum"("allocated") AS "allocated",
    "sum"("picked") AS "picked",
    "sum"("packed") AS "packed",
    GREATEST((((("sum"("on_hand") - "sum"("reserved")) - "sum"("allocated")) - "sum"("picked")) - "sum"("packed")), (0)::numeric) AS "available"
   FROM "public"."erp_inventory_balances" "b"
  GROUP BY "tenant_id", "sku_id", "warehouse_id";


ALTER VIEW "public"."erp_inventory_availability" OWNER TO "postgres";


