CREATE OR REPLACE VIEW "public"."erp_inventory_movement_history" WITH ("security_invoker"='on') AS
 SELECT "m"."tenant_id",
    "m"."id",
    "m"."occurred_at",
    "m"."movement_type",
    "s"."sku",
    "p"."name" AS "product_name",
    "m"."quantity",
    "m"."unit_cost",
    "m"."total_cost",
    "fw"."code" AS "from_warehouse",
    "fl"."code" AS "from_location",
    "tl"."code" AS "to_location",
    "m"."source_type",
    "m"."source_id",
    "m"."reference",
    "m"."reason",
    "m"."performed_by"
   FROM ((((("public"."erp_inventory_movements" "m"
     JOIN "public"."erp_product_skus" "s" ON (("s"."id" = "m"."sku_id")))
     JOIN "public"."erp_products" "p" ON (("p"."id" = "s"."product_id")))
     LEFT JOIN "public"."erp_warehouse_locations" "fl" ON (("fl"."id" = "m"."from_location_id")))
     LEFT JOIN "public"."erp_warehouse_locations" "tl" ON (("tl"."id" = "m"."to_location_id")))
     LEFT JOIN "public"."erp_warehouses" "fw" ON (("fw"."id" = "fl"."warehouse_id")));


ALTER VIEW "public"."erp_inventory_movement_history" OWNER TO "postgres";


