CREATE OR REPLACE VIEW "public"."erp_low_inventory" WITH ("security_invoker"='on') AS
 SELECT "p"."tenant_id",
    "s"."id" AS "sku_id",
    "s"."sku",
    "p"."name" AS "product_name",
    "w"."id" AS "warehouse_id",
    "w"."name" AS "warehouse_name",
    COALESCE("a"."on_hand", (0)::numeric) AS "on_hand",
    COALESCE("a"."reserved", (0)::numeric) AS "reserved",
    COALESCE("a"."available", (0)::numeric) AS "available",
    COALESCE("r"."reorder_point", "p"."reorder_point") AS "reorder_point",
    COALESCE("r"."safety_stock", "p"."safety_stock") AS "safety_stock",
        CASE
            WHEN (COALESCE("a"."available", (0)::numeric) <= (0)::numeric) THEN 'out_of_stock'::"text"
            WHEN (COALESCE("a"."available", (0)::numeric) <= COALESCE("r"."reorder_point", "p"."reorder_point")) THEN 'low_stock'::"text"
            ELSE 'healthy'::"text"
        END AS "stock_status"
   FROM (((("public"."erp_products" "p"
     JOIN "public"."erp_product_skus" "s" ON (("s"."product_id" = "p"."id")))
     CROSS JOIN "public"."erp_warehouses" "w")
     LEFT JOIN "public"."erp_inventory_availability" "a" ON ((("a"."sku_id" = "s"."id") AND ("a"."warehouse_id" = "w"."id"))))
     LEFT JOIN "public"."erp_replenishment_rules" "r" ON ((("r"."sku_id" = "s"."id") AND ("r"."warehouse_id" = "w"."id"))))
  WHERE (("p"."is_active" = true) AND ("s"."is_active" = true) AND ("w"."is_active" = true));


ALTER VIEW "public"."erp_low_inventory" OWNER TO "postgres";


