CREATE OR REPLACE VIEW "public"."erp_order_fulfillment_queue" WITH ("security_invoker"='on') AS
 SELECT "o"."tenant_id",
    "o"."id" AS "order_id",
    "o"."order_number",
    "o"."order_date",
    "o"."sla_due_at",
    "o"."priority",
    "o"."is_rush",
    "o"."status",
    "o"."fulfillment_method",
    "f"."id" AS "fulfillment_id",
    "f"."fulfillment_number",
    "f"."status" AS "fulfillment_status",
    "f"."warehouse_id",
    GREATEST((EXTRACT(epoch FROM ("now"() - "o"."order_date")) / (3600)::numeric), (0)::numeric) AS "order_age_hours"
   FROM ("public"."erp_orders" "o"
     LEFT JOIN "public"."erp_fulfillment_orders" "f" ON (("f"."order_id" = "o"."id")))
  WHERE ("o"."status" <> ALL (ARRAY['cancelled'::"public"."erp_order_status", 'completed'::"public"."erp_order_status", 'closed'::"public"."erp_order_status"]));


