CREATE OR REPLACE VIEW "public"."general_ledger" WITH ("security_invoker"='on') AS
 SELECT "l"."tenant_id",
    "e"."entry_date",
    "e"."reference",
    "e"."memo",
    "e"."source",
    "a"."code",
    "a"."name",
    "a"."type",
    "l"."description",
    "l"."debit",
    "l"."credit",
    "c"."firstName" AS "customer_first",
    "c"."lastName" AS "customer_last"
   FROM ((("public"."journal_lines" "l"
     JOIN "public"."journal_entries" "e" ON (("e"."id" = "l"."journal_id")))
     JOIN "public"."chart_of_accounts" "a" ON (("a"."id" = "l"."account_id")))
     LEFT JOIN "public"."customers" "c" ON (("c"."id" = "l"."customer_id")))
  ORDER BY "e"."entry_date", "e"."reference";


ALTER VIEW "public"."general_ledger" OWNER TO "postgres";


