CREATE OR REPLACE VIEW "public"."inventory_valuation" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "id" AS "item_id",
    "sku",
    "name",
    "quantity_on_hand",
    COALESCE("unit_cost", (0)::numeric) AS "avg_cost",
    ("quantity_on_hand" * COALESCE("unit_cost", (0)::numeric)) AS "total_value",
    "reorder_level",
        CASE
            WHEN ("quantity_on_hand" <= "reorder_level") THEN true
            ELSE false
        END AS "needs_reorder"
   FROM "public"."inventory_items" "i"
  WHERE (("tenant_id" IS NOT NULL) AND ("active" = true));


