CREATE OR REPLACE VIEW "public"."trial_balance" WITH ("security_invoker"='on') AS
 SELECT "tenant_id",
    "code",
    "name",
    "type",
        CASE
            WHEN ("balance" >= (0)::numeric) THEN "balance"
            ELSE (0)::numeric
        END AS "debit",
        CASE
            WHEN ("balance" < (0)::numeric) THEN (- "balance")
            ELSE (0)::numeric
        END AS "credit"
   FROM "public"."account_balances"
  WHERE (("total_debit" <> (0)::numeric) OR ("total_credit" <> (0)::numeric));


ALTER VIEW "public"."trial_balance" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_brand_facets" AS
 SELECT DISTINCT ON ("n"."id", "b"."id") "n"."id" AS "node_id",
    "n"."path" AS "node_path",
    "b"."id" AS "brand_id",
    "b"."name" AS "brand",
    "b"."slug" AS "brand_slug",
    (("bn"."path" || '/'::"text") || "b"."slug") AS "brand_page_path"
   FROM ((("public"."taxonomy_nodes" "n"
     JOIN "public"."taxonomy_nodes" "bn" ON ((("bn"."tenant_id" = "n"."tenant_id") AND (("bn"."path" = "n"."path") OR ("bn"."path" ~~ ("n"."path" || '/%'::"text"))))))
     JOIN "public"."brand_placements" "bp" ON ((("bp"."node_id" = "bn"."id") AND ("bp"."status" = 'published'::"text"))))
     JOIN "public"."brands" "b" ON ((("b"."id" = "bp"."brand_id") AND ("b"."status" = 'published'::"text"))))
  ORDER BY "n"."id", "b"."id", "bn"."depth";


ALTER VIEW "public"."v_brand_facets" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_brand_pages" AS
 SELECT "bp"."id" AS "placement_id",
    "b"."tenant_id",
    "b"."id" AS "brand_id",
    "b"."name" AS "brand",
    "b"."pricing_tier",
    "b"."logo_url",
    "n"."id" AS "node_id",
    "n"."name" AS "category",
    (("n"."path" || '/'::"text") || "b"."slug") AS "path",
    ( SELECT "json_agg"("json_build_object"('category', "n2"."name", 'path', (("n2"."path" || '/'::"text") || "b"."slug")) ORDER BY "n2"."path") AS "json_agg"
           FROM ("public"."brand_placements" "bp2"
             JOIN "public"."taxonomy_nodes" "n2" ON (("n2"."id" = "bp2"."node_id")))
          WHERE (("bp2"."brand_id" = "b"."id") AND ("bp2"."id" <> "bp"."id") AND ("bp2"."status" = 'published'::"text"))) AS "other_categories"
   FROM (("public"."brand_placements" "bp"
     JOIN "public"."brands" "b" ON (("b"."id" = "bp"."brand_id")))
     JOIN "public"."taxonomy_nodes" "n" ON (("n"."id" = "bp"."node_id")))
  WHERE (("bp"."status" = 'published'::"text") AND ("b"."status" = 'published'::"text"));


ALTER VIEW "public"."v_brand_pages" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_brand_publish_status" AS
 SELECT "b"."tenant_id",
    "b"."name" AS "brand",
    "b"."status" AS "brand_status",
    "n"."name" AS "category",
    "n"."path" AS "category_path",
    "bp"."status" AS "placement_status",
    "public"."brand_supply_source"("b"."id", "n"."id") AS "supply_source",
    ( SELECT "string_agg"(DISTINCT ((("po"."po_number" || ' ('::"text") || "po"."status") || ')'::"text"), ', '::"text") AS "string_agg"
           FROM (("public"."purchase_orders" "po"
             JOIN "public"."purchase_order_lines" "l" ON (("l"."purchase_order_id" = "po"."id")))
             JOIN "public"."taxonomy_nodes" "ln" ON (("ln"."id" = "l"."node_id")))
          WHERE (("po"."brand_id" = "b"."id") AND "public"."paths_related"("ln"."path", "n"."path"))) AS "purchase_orders",
    ( SELECT "string_agg"(((("s"."display_name" || ' ('::"text") || "a"."status") || ')'::"text"), ', '::"text") AS "string_agg"
           FROM ("public"."seller_brand_authorizations" "a"
             JOIN "public"."sellers" "s" ON (("s"."id" = "a"."seller_id")))
          WHERE ("a"."brand_id" = "b"."id")) AS "seller_authorizations",
        CASE
            WHEN (("bp"."status" = 'published'::"text") AND ("b"."status" = 'published'::"text")) THEN 'live'::"text"
            WHEN ("public"."brand_supply_source"("b"."id", "n"."id") IS NOT NULL) THEN 'ready to publish'::"text"
            ELSE 'waiting on purchase order or seller authorization'::"text"
        END AS "readiness"
   FROM (("public"."brand_placements" "bp"
     JOIN "public"."brands" "b" ON (("b"."id" = "bp"."brand_id")))
     JOIN "public"."taxonomy_nodes" "n" ON (("n"."id" = "bp"."node_id")));


ALTER VIEW "public"."v_brand_publish_status" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_buy_box" AS
 SELECT DISTINCT ON ("o"."variant_id") "o"."variant_id",
    "o"."id" AS "offer_id",
    "o"."seller_id",
    "s"."display_name" AS "seller",
    "s"."seller_type",
    "o"."price",
    "o"."compare_at_price",
    "o"."member_price",
    "st"."qty" AS "seller_stock"
   FROM (("public"."offers" "o"
     JOIN "public"."sellers" "s" ON ((("s"."id" = "o"."seller_id") AND ("s"."status" = 'approved'::"text"))))
     LEFT JOIN LATERAL ( SELECT COALESCE("sum"(GREATEST(("il"."on_hand" - "il"."reserved"), 0)), (0)::bigint) AS "qty"
           FROM "public"."inventory_levels" "il"
          WHERE (("il"."variant_id" = "o"."variant_id") AND ("il"."seller_id" = "o"."seller_id"))) "st" ON (true))
  WHERE ("o"."status" = 'active'::"text")
  ORDER BY "o"."variant_id", ("st"."qty" > 0) DESC, ("s"."seller_type" = 'first_party'::"text") DESC, "o"."price";


ALTER VIEW "public"."v_buy_box" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_node_filter_spec" AS
 SELECT "n"."id" AS "node_id",
    "n"."path",
    "f"."node_id" AS "defined_on_node_id",
    ("f"."node_id" <> "n"."id") AS "inherited",
    "f"."sort_order",
    "at"."name" AS "filter",
    "at"."slug" AS "query_param",
    "f"."value_source",
    "f"."display_type",
    "f"."ui_toggle",
    "f"."is_searchable",
    "f"."is_expanded_default",
    "f"."is_required",
    "f"."allow_new_values",
    ( SELECT "json_agg"("json_build_object"('value', "av"."value", 'slug', "av"."slug") ORDER BY "nfv"."sort_order") AS "json_agg"
           FROM ("public"."node_filter_values" "nfv"
             JOIN "public"."attribute_values" "av" ON (("av"."id" = "nfv"."attribute_value_id")))
          WHERE (("nfv"."node_filter_id" = "f"."id") AND "nfv"."is_visible")) AS "allowed_values"
   FROM (("public"."taxonomy_nodes" "n"
     JOIN "public"."node_filters" "f" ON (("f"."node_id" = COALESCE("public"."effective_filter_node"("n"."id"), "n"."id"))))
     JOIN "public"."attributes" "at" ON (("at"."id" = "f"."attribute_id")));


ALTER VIEW "public"."v_node_filter_spec" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_cms_product_form" AS
 SELECT "node_id",
    "path",
    "sort_order",
    "filter",
    "query_param",
        CASE "value_source"
            WHEN 'predefined'::"text" THEN
            CASE
                WHEN "allow_new_values" THEN 'select_or_add'::"text"
                ELSE 'select_locked'::"text"
            END
            WHEN 'cms'::"text" THEN 'free_entry'::"text"
            WHEN 'brand'::"text" THEN 'brand_picker'::"text"
            WHEN 'computed'::"text" THEN 'derived (not entered)'::"text"
            ELSE NULL::"text"
        END AS "input_type",
    "is_required",
    "allowed_values"
   FROM "public"."v_node_filter_spec";


ALTER VIEW "public"."v_cms_product_form" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_groomer_commission_report" WITH ("security_invoker"='on') AS
 SELECT "e"."tenant_id",
    "e"."staff_id",
    "s"."display_name" AS "groomer_name",
    ("date_trunc"('month'::"text", ("e"."earned_on")::timestamp with time zone))::"date" AS "period_month",
    "count"(*) FILTER (WHERE ("e"."entry_type" = 'earned'::"text")) AS "transactions",
    "sum"("e"."basis_amount") AS "basis_total",
    "sum"("e"."tips_amount") AS "tips_total",
    "sum"("e"."retail_amount") AS "retail_total",
    "sum"("e"."commission_amount") FILTER (WHERE ("e"."status" = ANY (ARRAY['approved'::"text", 'paid'::"text"]))) AS "commission_earned",
    "sum"("e"."commission_amount") FILTER (WHERE ("e"."status" = 'pending'::"text")) AS "commission_pending",
    "sum"("e"."commission_amount") FILTER (WHERE ("e"."status" = 'paid'::"text")) AS "commission_paid",
    "sum"("e"."commission_amount") FILTER (WHERE ("e"."entry_type" = 'reversal'::"text")) AS "commission_reversed"
   FROM ("public"."crm_commission_entries" "e"
     JOIN "public"."crm_staff" "s" ON (("s"."id" = "e"."staff_id")))
  WHERE ("e"."status" <> 'void'::"text")
  GROUP BY "e"."tenant_id", "e"."staff_id", "s"."display_name", ("date_trunc"('month'::"text", ("e"."earned_on")::timestamp with time zone));


ALTER VIEW "public"."v_groomer_commission_report" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_new_filter_values_review" AS
 SELECT "n"."path",
    "at"."name" AS "filter",
    "av"."value",
    "nfv"."added_by",
    "nfv"."created_at"
   FROM (((("public"."node_filter_values" "nfv"
     JOIN "public"."node_filters" "f" ON (("f"."id" = "nfv"."node_filter_id")))
     JOIN "public"."taxonomy_nodes" "n" ON (("n"."id" = "f"."node_id")))
     JOIN "public"."attributes" "at" ON (("at"."id" = "f"."attribute_id")))
     JOIN "public"."attribute_values" "av" ON (("av"."id" = "nfv"."attribute_value_id")))
  WHERE "nfv"."needs_review";


ALTER VIEW "public"."v_new_filter_values_review" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_node_breadcrumbs" AS
 SELECT "n"."id" AS "node_id",
    "n"."path",
    "json_agg"("json_build_object"('name', COALESCE("a"."display_name", "a"."name"), 'path', "a"."path") ORDER BY "a"."depth") AS "crumbs"
   FROM ("public"."taxonomy_nodes" "n"
     JOIN "public"."taxonomy_nodes" "a" ON ((("a"."tenant_id" = "n"."tenant_id") AND (("n"."path" = "a"."path") OR ("n"."path" ~~ ("a"."path" || '/%'::"text"))))))
  GROUP BY "n"."id", "n"."path";


ALTER VIEW "public"."v_node_breadcrumbs" OWNER TO "postgres";


