    "path",
    "sort_order",
    "is_associated",
    "is_featured"
   FROM "public"."taxonomy_nodes" "c"
  WHERE (("status" = 'published'::"text") AND ("parent_id" IS NOT NULL));


ALTER VIEW "public"."v_node_children" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_orphan_pages" AS
 SELECT "p"."tenant_id",
    'product'::"text" AS "kind",
    ('/shop/product/'::"text" || "p"."slug") AS "path",
    'published product is not in any published category'::"text" AS "issue"
   FROM "public"."products" "p"
  WHERE (("p"."status" = 'published'::"text") AND (NOT (EXISTS ( SELECT 1
           FROM ("public"."product_nodes" "pn"
             JOIN "public"."taxonomy_nodes" "n" ON ((("n"."id" = "pn"."node_id") AND ("n"."status" = 'published'::"text"))))
          WHERE ("pn"."product_id" = "p"."id")))))
UNION ALL
 SELECT "r"."tenant_id",
    'related_search'::"text" AS "kind",
    COALESCE("r"."legacy_path", ('/shop/search/'::"text" || "r"."slug")) AS "path",
    'related search page has no published target category'::"text" AS "issue"
   FROM "public"."related_search_pages" "r"
  WHERE (("r"."status" = 'published'::"text") AND ("r"."lifecycle" = 'active'::"text") AND (NOT (EXISTS ( SELECT 1
           FROM "public"."taxonomy_nodes" "n"
          WHERE (("n"."id" = "r"."target_node_id") AND ("n"."status" = 'published'::"text"))))))
UNION ALL
 SELECT "n"."tenant_id",
    'category'::"text" AS "kind",
    "n"."path",
    'published category under an unpublished parent'::"text" AS "issue"
   FROM ("public"."taxonomy_nodes" "n"
     JOIN "public"."taxonomy_nodes" "par" ON (("par"."id" = "n"."parent_id")))
  WHERE (("n"."status" = 'published'::"text") AND ("par"."status" <> 'published'::"text"))
UNION ALL
 SELECT "n"."tenant_id",
    'category'::"text" AS "kind",
    "n"."path",
    'click depth > 3 (category pages must be within 3 clicks of /shop)'::"text" AS "issue"
   FROM "public"."taxonomy_nodes" "n"
  WHERE (("n"."status" = 'published'::"text") AND ("n"."depth" > 3) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."related_search_pages" "r"
          WHERE (("r"."target_node_id" = "n"."id") AND ("r"."lifecycle" = 'active'::"text"))))));


ALTER VIEW "public"."v_orphan_pages" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_pickup_availability" AS
 SELECT "il"."variant_id",
    "l"."id" AS "location_id",
    "l"."name" AS "location",
    "l"."city",
    GREATEST(("il"."on_hand" - "il"."reserved"), 0) AS "available"
   FROM (("public"."inventory_levels" "il"
     JOIN "public"."locations" "l" ON ((("l"."id" = "il"."location_id") AND "l"."is_pickup_enabled" AND ("l"."status" = 'active'::"text"))))
     JOIN "public"."offers" "o" ON ((("o"."variant_id" = "il"."variant_id") AND ("o"."seller_id" = "il"."seller_id") AND ("o"."status" = 'active'::"text"))));


ALTER VIEW "public"."v_pickup_availability" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_product_rating" AS
 SELECT "product_id",
    "round"("avg"("rating"), 2) AS "rating_value",
    "count"(*) AS "review_count"
   FROM "public"."reviews"
  WHERE ("status" = 'published'::"text")
  GROUP BY "product_id";


ALTER VIEW "public"."v_product_rating" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_variant_stock" AS
 SELECT "v"."id" AS "variant_id",
    "v"."product_id",
    COALESCE("sum"(GREATEST(("il"."on_hand" - "il"."reserved"), 0)) FILTER (WHERE ("o"."id" IS NOT NULL)), (0)::bigint) AS "sellable_qty"
   FROM (("public"."product_variants" "v"
     LEFT JOIN "public"."inventory_levels" "il" ON (("il"."variant_id" = "v"."id")))
     LEFT JOIN "public"."offers" "o" ON ((("o"."variant_id" = "v"."id") AND ("o"."seller_id" = "il"."seller_id") AND ("o"."status" = 'active'::"text"))))
  GROUP BY "v"."id", "v"."product_id";


ALTER VIEW "public"."v_variant_stock" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_variant_availability" AS
 SELECT "variant_id",
    "product_id",
    "sellable_qty",
        CASE
            WHEN ("sellable_qty" > 0) THEN 'InStock'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM ("public"."purchase_order_lines" "l"
                 JOIN "public"."purchase_orders" "po" ON (("po"."id" = "l"."purchase_order_id")))
              WHERE (("l"."variant_id" = "s"."variant_id") AND ("po"."status" = ANY (ARRAY['approved'::"public"."order_status", 'partially_received'::"public"."order_status"])) AND ("l"."qty_received" < "l"."qty_ordered") AND ("po"."expected_date" IS NOT NULL)))) THEN 'PreOrder'::"text"
            ELSE 'OutOfStock'::"text"
        END AS "availability"
   FROM "public"."v_variant_stock" "s";


ALTER VIEW "public"."v_variant_availability" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_product_cards" AS
 SELECT "p"."id" AS "product_id",
    "p"."tenant_id",
    "p"."name",
    ('/shop/product/'::"text" || "p"."slug") AS "path",
    "b"."name" AS "brand",
    ( SELECT "m"."url"
           FROM "public"."product_media" "m"
          WHERE ("m"."product_id" = "p"."id")
          ORDER BY "m"."sort_order"
         LIMIT 1) AS "image_url",
    "min"("bb"."price") AS "price_from",
    "min"("bb"."compare_at_price") AS "compare_at_from",
    "min"("bb"."member_price") AS "member_price_from",
    "r"."rating_value",
    COALESCE("r"."review_count", (0)::bigint) AS "review_count",
        CASE
            WHEN "bool_or"(("av"."availability" = 'InStock'::"text")) THEN 'InStock'::"text"
            WHEN "bool_or"(("av"."availability" = 'PreOrder'::"text")) THEN 'PreOrder'::"text"
            ELSE 'OutOfStock'::"text"
        END AS "availability"
   FROM ((((("public"."products" "p"
     LEFT JOIN "public"."brands" "b" ON (("b"."id" = "p"."brand_id")))
     LEFT JOIN "public"."product_variants" "v" ON ((("v"."product_id" = "p"."id") AND ("v"."status" = 'active'::"text"))))
     LEFT JOIN "public"."v_buy_box" "bb" ON (("bb"."variant_id" = "v"."id")))
     LEFT JOIN "public"."v_variant_availability" "av" ON (("av"."variant_id" = "v"."id")))
     LEFT JOIN "public"."v_product_rating" "r" ON (("r"."product_id" = "p"."id")))
  WHERE ("p"."status" = 'published'::"text")
  GROUP BY "p"."id", "p"."tenant_id", "p"."name", "p"."slug", "b"."name", "r"."rating_value", "r"."review_count";


ALTER VIEW "public"."v_product_cards" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_related_search_links" AS
 SELECT "s"."node_id",
    "s"."page_id",
    "s"."query_text",
    "s"."path",
    "s"."reason",
    "s"."rnk"
   FROM ( SELECT "n"."id" AS "node_id",
            "r"."id" AS "page_id",
            "r"."query_text",
            COALESCE("r"."legacy_path", ('/shop/search/'::"text" || "r"."slug")) AS "path",
            'subtree'::"text" AS "reason",
            "row_number"() OVER (PARTITION BY "n"."id" ORDER BY "r"."legacy_traffic" DESC, "r"."query_text") AS "rnk"
           FROM (("public"."taxonomy_nodes" "n"
             JOIN "public"."taxonomy_nodes" "t" ON ((("t"."tenant_id" = "n"."tenant_id") AND (("t"."path" = "n"."path") OR ("t"."path" ~~ ("n"."path" || '/%'::"text"))))))
             JOIN "public"."related_search_pages" "r" ON ((("r"."target_node_id" = "t"."id") AND ("r"."status" = 'published'::"text") AND ("r"."lifecycle" = 'active'::"text"))))) "s"
  WHERE ("s"."rnk" <= 8)
UNION ALL
 SELECT "p"."node_id",
    "p"."page_id",
    "p"."query_text",
    "p"."path",
    "p"."reason",
    "p"."rnk"
   FROM ( SELECT "n"."id",
            "r"."id",
            "r"."query_text",
            COALESCE("r"."legacy_path", ('/shop/search/'::"text" || "r"."slug")) AS "coalesce",
            'parent'::"text" AS "text",
            "row_number"() OVER (PARTITION BY "n"."id" ORDER BY "r"."legacy_traffic" DESC, "r"."query_text") AS "row_number"
           FROM ("public"."taxonomy_nodes" "n"
             JOIN "public"."related_search_pages" "r" ON ((("r"."target_node_id" = "n"."parent_id") AND ("r"."status" = 'published'::"text") AND ("r"."lifecycle" = 'active'::"text"))))) "p"("node_id", "page_id", "query_text", "path", "reason", "rnk")
  WHERE ("p"."rnk" <= 4);


ALTER VIEW "public"."v_related_search_links" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_routes" AS
 SELECT "t"."id" AS "tenant_id",
    '/shop'::"text" AS "path",
    'shop_landing'::"text" AS "page_type",
    NULL::"uuid" AS "entity_id",
    NULL::"text" AS "animal",
    "t"."updated_at" AS "lastmod",
    'sitemap-shop'::"text" AS "sitemap"
   FROM "public"."tenants" "t"
  WHERE ("t"."status" = 'active'::"text")
UNION ALL
 SELECT "n"."tenant_id",
    "n"."path",
    "n"."node_type" AS "page_type",
    "n"."id" AS "entity_id",
    "a"."slug" AS "animal",
    "n"."updated_at" AS "lastmod",
    ('sitemap-'::"text" || "a"."slug") AS "sitemap"
   FROM ("public"."taxonomy_nodes" "n"
     JOIN "public"."taxonomy_nodes" "a" ON (("a"."id" = "n"."animal_id")))
  WHERE (("n"."status" = 'published'::"text") AND (NOT (EXISTS ( SELECT 1
           FROM "public"."taxonomy_nodes" "anc"
          WHERE (("anc"."tenant_id" = "n"."tenant_id") AND ("n"."path" ~~ ("anc"."path" || '/%'::"text")) AND ("anc"."status" <> 'published'::"text"))))))
UNION ALL
 SELECT "bp"."tenant_id",
    (("n"."path" || '/'::"text") || "b"."slug") AS "path",
    'brand'::"text" AS "page_type",
    "bp"."id" AS "entity_id",
    "a"."slug" AS "animal",
    GREATEST("bp"."updated_at", "b"."updated_at") AS "lastmod",
    ('sitemap-'::"text" || "a"."slug") AS "sitemap"
   FROM ((("public"."brand_placements" "bp"
     JOIN "public"."brands" "b" ON (("b"."id" = "bp"."brand_id")))
     JOIN "public"."taxonomy_nodes" "n" ON (("n"."id" = "bp"."node_id")))
     JOIN "public"."taxonomy_nodes" "a" ON (("a"."id" = "n"."animal_id")))
  WHERE (("bp"."status" = 'published'::"text") AND ("b"."status" = 'published'::"text") AND ("n"."status" = 'published'::"text") AND ("a"."status" = 'published'::"text"))
UNION ALL
 SELECT "p"."tenant_id",
    ('/shop/product/'::"text" || "p"."slug") AS "path",
    'product'::"text" AS "page_type",
    "p"."id" AS "entity_id",
    NULL::"text" AS "animal",
    "p"."updated_at" AS "lastmod",
    'sitemap-products'::"text" AS "sitemap"
   FROM "public"."products" "p"
  WHERE ("p"."status" = 'published'::"text")
UNION ALL
 SELECT "r"."tenant_id",
    COALESCE("r"."legacy_path", ('/shop/search/'::"text" || "r"."slug")) AS "path",
    'related_search'::"text" AS "page_type",
    "r"."id" AS "entity_id",
    "a"."slug" AS "animal",
    "r"."updated_at" AS "lastmod",
    'sitemap-legacy'::"text" AS "sitemap"
   FROM (("public"."related_search_pages" "r"
     LEFT JOIN "public"."taxonomy_nodes" "tn" ON (("tn"."id" = "r"."target_node_id")))
     LEFT JOIN "public"."taxonomy_nodes" "a" ON (("a"."id" = "tn"."animal_id")))
  WHERE (("r"."status" = 'published'::"text") AND ("r"."lifecycle" = 'active'::"text"));


ALTER VIEW "public"."v_routes" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_sitemap" AS
 SELECT "r"."tenant_id",
    "r"."sitemap" AS "sitemap_file",
    (('https://'::"text" || "t"."primary_domain") || "r"."path") AS "loc",
    "r"."lastmod",
    "r"."page_type"
   FROM ("public"."v_routes" "r"
     JOIN "public"."tenants" "t" ON (("t"."id" = "r"."tenant_id")))
  WHERE ("t"."primary_domain" IS NOT NULL);


ALTER VIEW "public"."v_sitemap" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_supply_service_links" AS
 SELECT "m"."node_id",
    "n"."path" AS "shop_path",
    "s"."id" AS "service_id",
    "s"."name" AS "service",
    "s"."starts_at_price",
    "s"."member_price",
    ((('/book?service='::"text" || "s"."slug") || '&source=shop-'::"text") || "replace"(TRIM(LEADING '/'::"text" FROM "n"."path"), '/'::"text", '-'::"text")) AS "book_url",
    "m"."is_default"
   FROM (("public"."supply_service_map" "m"
     JOIN "public"."taxonomy_nodes" "n" ON (("n"."id" = "m"."node_id")))
     JOIN "public"."grooming_services" "s" ON ((("s"."id" = "m"."service_id") AND ("s"."status" = 'active'::"text"))));


ALTER VIEW "public"."v_supply_service_links" OWNER TO "postgres";


