   FROM "public"."tenant_memberships" "tm"
  WHERE (("tm"."user_id" = "auth"."uid"()) AND ("tm"."tenant_id" = "tenant_memberships"."tenant_id") AND ("tm"."role" = ANY (ARRAY['super_admin'::"text", 'owner'::"text", 'admin'::"text"])) AND ("tm"."active" = true) AND ("tm"."status" = 'active'::"text")))))) WITH CHECK (("public"."platform_is_admin"() OR (EXISTS ( SELECT 1
